// `ActiveContext` + the race-safe `derive_active_context` were
// hoisted to `commands::route_to_context` so the MCP wrappers here and the Tauri
// route command share ONE deriver. This module keeps a thin `ErrorData` shim
// (below) over the shared `String`-error version so the 9 existing call-sites
// are unchanged.
use crate::commands::route_to_context::ActiveContext;

/// RF-perf-9: back the validator's `StoryIdIndex` seam with the frontmatter cache's
/// `O(1)` aux `story_id` index — this is the bridge that turns `validate_story`'s
/// former org-wide `O(N)` `(id, path)` enumeration into a point lookup. Lives here (the
/// MCP↔cache bridge layer) so the pure validator stays decoupled from the cache type.
impl story_authoring::StoryIdIndex for crate::install::frontmatter_cache::FrontmatterCache {
    fn paths_for_story_id(&self, story_id: &str) -> Vec<PathBuf> {
        self.by_story_id(story_id)
            .iter()
            .map(|e| e.path.clone())
            .collect()
    }
}

/// Thin MCP adapter over the shared
/// [`crate::commands::route_to_context::derive_active_context`].
/// Maps its plain-`String` error to [`ErrorData::invalid_params`] so the skill
/// surfaces the three reachable precondition cases (no active team / no
/// selected local profile / home dir unavailable) conversationally. The two
/// unreachable "singleton not registered" cases also collapse to
/// `invalid_params` — acceptable, as they never fire in a running app.
async fn derive_active_context(app: &AppHandle) -> Result<ActiveContext, ErrorData> {
    crate::commands::route_to_context::derive_active_context(app)
        .await
        .map_err(|msg| ErrorData::invalid_params(msg, None))
}

/// The `"owner/repo" -> RepoAccount` map that enriches `list_source_repos`.
/// Built-in service accounts are retired (local profiles replaced sign-in), so no
/// repo has a bound account and every entry reports `null`.
async fn resolve_bound_accounts(
    app: &AppHandle,
    ctx: &ActiveContext,
) -> HashMap<String, story_authoring::RepoAccount> {
    let _ = (app, ctx);
    HashMap::new()
}

/// Resolve the active org's root directory (`{codesense_home}/users/{uid}/
/// orgs/{org}`). Shared by the two worktree-config MCP verbs
/// (`read_worktree_config` / `write_worktree_config`) so they resolve the
/// content-layer destination root identically and can never drift.
async fn derive_active_org_root(app: &AppHandle) -> Result<PathBuf, ErrorData> {
    let ctx = derive_active_context(app).await?;
    crate::commands::await_blocking("resolve active org root", move || {
        crate::context_repo::path_to_org_root(&ctx.codesense_home, &ctx.principal(), &ctx.org_slug)
    })
    .await
    .map_err(|e| ErrorData::invalid_params(e, None))
}

async fn derive_active_worktree_context(
    app: &AppHandle,
) -> Result<(PathBuf, commands::worktree::WorktreeConfigAuthority), ErrorData> {
    let ctx = derive_active_context(app).await?;
    let principal = ctx.principal();
    let org_root =
        crate::context_repo::path_to_org_root(&ctx.codesense_home, &principal, &ctx.org_slug)
            .map_err(|e| ErrorData::invalid_params(e, None))?;
    let team = ctx
        .team_name
        .ok_or_else(|| ErrorData::invalid_params("no active team selected".to_owned(), None))?;
    let authority = commands::worktree::WorktreeConfigAuthority {
        codesense_home: ctx.codesense_home,
        principal,
        team,
    };
    Ok((org_root, authority))
}

/// Tool-discovery meta tools. Finding a tool by keyword goes:
/// `codesense_search_tools` → `codesense_get_tool_schema` → call the tool by name
/// (or `codesense_call_tool` as a last-resort escape hatch).
const META_TOOL_NAMES: &[&str] = &[
    "codesense_search_tools",
    "codesense_get_tool_schema",
    "codesense_call_tool",
];

#[derive(Clone)]
pub struct CodesenseHandler {
    remote_authority: Option<super::remote_authority::RemoteAuthority>,
    /// The tab identity verified at initialize against its hosted process or captured
    /// relay child. Shared by rmcp's clones for this connection.
    caller_session: Arc<std::sync::RwLock<Option<super::local_identity::Binding>>>,
    local_tools: Arc<std::sync::Mutex<super::local_tools::ConnectionState>>,
    /// The kernel-verified process on the other end of the local
    /// MCP socket (the agent's bridge). A tool that acts for "your own
    /// session" binds its `sessionId` to it.
    local_peer: Option<codesense_pty_core::activity::peer::PeerProcess>,
    app_handle: AppHandle,
    #[allow(dead_code)]
    tool_router: ToolRouter<Self>,
}

/// A remote tab speaks as its captured authority; a sessionless task cannot be human.
fn remote_inbox_caller<'a>(
    tab: Option<(&'a str, &'a str)>,
) -> Result<crate::commands::agent_inbox::Caller<'a>, ErrorData> {
    use crate::commands::agent_inbox::Caller;
    if let Some((handle, _)) = tab {
        return Ok(Caller::Authenticated(handle));
    }
    Err(super::local_identity::refused())
}

pub(crate) use super::local_identity::inbox_caller as local_inbox_caller;

impl CodesenseHandler {
    pub fn new(app_handle: AppHandle) -> Self {
        Self {
            remote_authority: None,
            caller_session: Arc::default(),
            local_tools: Arc::default(),
            local_peer: None,
            app_handle,
            tool_router: Self::served_tool_router(),
        }
    }

    pub(crate) fn local_tools_lifetime(&self) -> super::local_tools::Lifetime {
        super::local_tools::Lifetime(self.local_tools.clone())
    }

    /// The handler of a local MCP socket connection whose peer is `peer`.
    pub(crate) fn with_local_peer(
        mut self,
        peer: Option<codesense_pty_core::activity::peer::PeerProcess>,
    ) -> Self {
        self.local_peer = peer;
        self
    }

    pub(crate) fn new_remote(
        app_handle: AppHandle,
        authority: super::remote_authority::RemoteAuthority,
    ) -> Self {
        Self {
            app_handle,
            remote_authority: Some(authority),
            caller_session: Arc::default(),
            local_tools: Arc::default(),
            local_peer: None,
            tool_router: Self::served_tool_router(),
        }
    }

    /// The verified tab this connection speaks for; an unbound MCP caller has none.
    fn connection_session(&self) -> Option<String> {
        if let Some(authority) = &self.remote_authority {
            // A remote connection is identified by its authority alone, never by what
            // its client claims.
            return authority
                .caller_identity()
                .map(|(handle, _)| handle.to_string());
        }
        super::local_identity::stored_session(&self.caller_session)
    }

    /// The session a session-scoped tool acts for: the `sessionId` it was given, else
    /// the session this connection runs as. On a remote connection that is the
    /// machine-side session it authenticated as (what the transport checks bind to),
    /// not its tab handle. Refused when neither names one.
    fn own_session(&self, claimed: Option<&str>) -> Result<String, ErrorData> {
        let connection = match &self.remote_authority {
            Some(authority) => authority.caller_session().map(str::to_string),
            None => self.connection_session(),
        };
        own_session(claimed, connection)
    }

    fn verified_handle(&self, session: &str) -> Option<String> {
        if let Some(authority) = &self.remote_authority {
            return authority
                .caller_identity()
                .filter(|(_, own)| *own == session)
                .map(|(handle, _)| handle.to_owned());
        }
        self.app_handle
            .try_state::<crate::commands::dashboard_launch::DashboardLaunchState>()
            .and_then(|launch| launch.handle_for_session(session))
    }

    /// Weft follows the captured caller team, even while the UI views another team.
    async fn weft_store_path(&self) -> Result<PathBuf, ErrorData> {
        self.weft_store().await.map(|(path, _)| path)
    }

    /// [`Self::weft_store_path`] with the team whose store it is.
    async fn weft_store(
        &self,
    ) -> Result<(PathBuf, crate::commands::dashboard_launch::LaunchTeam), ErrorData> {
        let context = self.context().await?;
        let (session, remote_team) = match &self.remote_authority {
            Some(authority) => (
                authority.caller_session().map(str::to_owned),
                crate::commands::dashboard_launch::launch_team_from_key(authority.team_key()),
            ),
            None => (self.connection_session(), None),
        };
        let launch = self
            .app_handle
            .try_state::<crate::commands::dashboard_launch::DashboardLaunchState>();
        super::local_identity::weft_store(
            &context,
            session.as_deref(),
            // Remote callers are granted only the authority's captured team.
            if self.remote_authority.is_none() {
                launch.as_deref()
            } else {
                None
            },
            remote_team,
        )
        .map_err(|error| ErrorData::invalid_params(error, None))
    }

    fn queue_caller(&self, session: &str) -> crate::weft::queue::QueueCaller {
        if let Some(authority) = &self.remote_authority {
            return super::local_identity::queue_caller(session, None, authority.queue_owner());
        }
        let launch = self
            .app_handle
            .try_state::<crate::commands::dashboard_launch::DashboardLaunchState>();
        super::local_identity::queue_caller(session, launch.as_deref(), None)
    }

    /// Inbox attribution follows the verified connection; an explicit id must agree.
    fn inbox_caller<'a>(
        &'a self,
        explicit: Option<&'a str>,
        connection: Option<&'a str>,
    ) -> Result<crate::commands::agent_inbox::Caller<'a>, ErrorData> {
        match &self.remote_authority {
            Some(authority) => remote_inbox_caller(authority.caller_identity()),
            None => local_inbox_caller(explicit, connection),
        }
    }

    async fn bind_local_arguments(
        &self,
        name: &str,
        arguments: &mut serde_json::Map<String, serde_json::Value>,
    ) -> Result<(), ErrorData> {
        let session = self.connection_session();
        if let Some(binding) = super::local_identity::stored(&self.caller_session) {
            let app = self.app_handle.clone();
            let peer = self.local_peer;
            commands::await_blocking("mcp.revalidate_caller", move || {
                Ok(super::local_identity::revalidate(
                    &binding,
                    peer,
                    local_session_lookup(&app, &binding.session),
                ))
            })
            .await
            .unwrap_or_else(|_| Err(super::local_identity::refused()))?;
        }
        let handle = session.as_deref().and_then(|session| {
            self.app_handle
                .try_state::<crate::commands::dashboard_launch::DashboardLaunchState>()
                .and_then(|state| state.handle_for_session(session))
        });
        super::local_identity::arguments(name, arguments, session.as_deref(), handle.as_deref())
    }

    /// `send_to_session` typed `text` into the session under `handle` (local or remote):
    /// record it in that session's conversation as from this connection's tab (the human
    /// outside any tab). Logging never fails the send, since the text is already typed.
    async fn log_typed_into_terminal(&self, handle: &str, text: &str) {
        let host = crate::commands::agent_inbox::AppInboxHost {
            app: self.app_handle.clone(),
        };
        // A remote task runs in no tab: it has no inbox identity, and logging its text
        // with no sender would record it as typed by the human.
        if self
            .remote_authority
            .as_ref()
            .is_some_and(|authority| authority.caller_tab().is_none())
        {
            return;
        }
        let connection = self.connection_session();
        if let Err(e) = crate::commands::agent_inbox::log_terminal_send(
            &host,
            connection.as_deref(),
            handle,
            text,
        )
        .await
        {
            log::warn!(target: "inbox", "send_to_session to {handle} not logged: {e}");
        }
    }

    /// The org and context repo a context-repo verb acts on: the caller's, not the one
    /// shown in the app (see [`crate::commands::agent_read_model::caller_org`]).
    async fn caller_context_repo(
        &self,
        target: ContextRepoTarget,
    ) -> Result<(String, PathBuf), ErrorData> {
        let host = crate::commands::agent_inbox::AppInboxHost {
            app: self.app_handle.clone(),
        };
        let own_session = self.connection_session();
        let own_org = self.remote_team().map(|t| t.org);
        let org = crate::commands::agent_read_model::caller_org(
            &host,
            target.org.as_deref(),
            target.session_id.as_deref(),
            own_session.as_deref(),
            own_org.as_deref(),
        )
        .map_err(|e| ErrorData::invalid_params(e, None))?;
        let ctx = derive_active_context(&self.app_handle).await?;
        let org = org.unwrap_or_else(|| ctx.org_slug.clone());
        let root_org = org.clone();
        let root = crate::commands::await_blocking("resolve context repo root", move || {
            crate::context_repo::path_to_org_root(&ctx.codesense_home, &ctx.principal(), &root_org)
        })
        .await
        .map_err(|e| ErrorData::invalid_params(e, None))?;
        Ok((org, root))
    }

    /// The team a remote agent's tab runs in, for a team-scoped read that names none.
    /// `None` for a local caller (the UI-active team applies).
    fn remote_team(&self) -> Option<crate::commands::agent_inbox::InboxTeam> {
        let (org, team) = self.remote_authority.as_ref()?.team_key().split_once(':')?;
        Some(crate::commands::agent_inbox::InboxTeam {
            org: org.to_string(),
            team: team.to_string(),
        })
    }

    async fn caller_scope(&self) -> crate::context_repo::caller_scope::CallerScope {
        crate::context_repo::caller_scope::for_session(
            &self.app_handle,
            self.connection_session().as_deref(),
            self.remote_team().map(Into::into),
        )
        .await
    }

    /// Record the tab a client's `initialize` proved.
    fn note_initialize(&self, binding: Option<super::local_identity::Binding>) {
        super::local_identity::note_initialize(&self.caller_session, binding);
    }
    /// What the transport knows about this caller,
    /// and, on this Mac, the process the `claimed` session runs.
    async fn transport_identity(
        &self,
        claimed: &str,
    ) -> Result<
        (
            crate::delivery::authority::TransportIdentity,
            Option<codesense_pty_core::activity::peer::PeerProcess>,
        ),
        ErrorData,
    > {
        use crate::delivery::authority::TransportIdentity;
        require_session_id(claimed)?;
        let identity = match (&self.remote_authority, self.local_peer) {
            (Some(authority), _) => {
                authority.validate().await?;
                TransportIdentity::Reverse {
                    machine: authority.machine_id().to_string(),
                    session: authority.caller_session().map(str::to_string),
                    task: authority.caller_task().map(str::to_string),
                }
            }
            (None, Some(peer)) => TransportIdentity::LocalPeer(peer),
            (None, None) => TransportIdentity::Anonymous,
        };
        let root = match identity {
            TransportIdentity::LocalPeer(_) => {
                // This connection's own tab may fall back to the root it proved.
                let cached = super::local_identity::stored(&self.caller_session)
                    .filter(|binding| binding.session == claimed)
                    .and_then(|binding| binding.root);
                let app = self.app_handle.clone();
                let session = claimed.to_string();
                commands::await_blocking("mcp.session_root", move || {
                    Ok(super::local_identity::usable_root(
                        local_session_lookup(&app, &session),
                        cached,
                    ))
                })
                .await
                .unwrap_or(None)
            }
            _ => None,
        };
        Ok((identity, root))
    }

    /// Dispatch revalidates the launch proof before entering a receiver. Reuse that
    /// verified identity here: a relay bridge is outside the tab's direct ancestry.
    pub(crate) async fn authenticated_session(
        &self,
        claimed: &str,
    ) -> Result<crate::delivery::authority::SessionRef, ErrorData> {
        let session = self.own_session(Some(claimed))?;
        let machine = self
            .remote_authority
            .as_ref()
            .map_or(crate::commands::machines::LOCAL_MACHINE_ID, |authority| {
                authority.machine_id()
            });
        Ok(crate::delivery::authority::SessionRef::new(
            machine, session,
        ))
    }

    async fn records_reply(
        &self,
        operation: &'static str,
        mut params: super::records_tools::RecordsParams,
    ) -> Result<CallToolResult, ErrorData> {
        let scope = self.caller_scope().await;
        params.session_id = Some(self.own_session(params.session_id.as_deref())?);
        let (home, user_id) = if let Some(authority) = &self.remote_authority {
            let context = authority.context().await?;
            (context.codesense_home, context.user_id)
        } else {
            commands::route_to_context::resolve_ambient(&self.app_handle)
                .await
                .map_err(|message| ErrorData::invalid_params(message, None))?
        };
        let context = if let Some(authority) = &self.remote_authority {
            let ctx = authority.context().await?;
            Some(commands::dashboard_launch::LaunchTeam {
                org: ctx.org_slug,
                team: ctx.team_name.unwrap_or_default(),
            })
        } else if let Some(session) = params.session_id.as_deref() {
            super::identity_tools::running_session(&self.app_handle, session)
                .await
                .map_err(|e| ErrorData::invalid_params(e, None))?
                .team
        } else {
            commands::route_to_context::derive_active_context(&self.app_handle)
                .await
                .ok()
                .map(|ctx| commands::dashboard_launch::LaunchTeam {
                    org: ctx.org_slug,
                    team: ctx.team_name.unwrap_or_default(),
                })
        };
        if context.is_none() && params.session_id.is_some() && params.org.is_none() {
            return envelope_json(&super::tool_envelope::ToolEnvelope::<()>::Validation {
                message: "the session has no org context: pass org and team explicitly".into(),
            });
        }
        super::records_tools::bind_defaults(&mut params, context.as_ref());
        let Some(org) = params.org.clone() else {
            return envelope_json(&super::tool_envelope::ToolEnvelope::<()>::Validation {
                message: "no org context: pass org and team explicitly".into(),
            });
        };
        let actor = self.notes_actor(params.session_id.as_deref()).await?;
        let team = params.team.clone();
        let index = self
            .app_handle
            .try_state::<crate::context_query::ContextIndexService>()
            .map(|s| s.inner().clone());
        let result = commands::await_blocking("mcp.records", move || {
            Ok::<_, String>(
                crate::records::binding::Binding::from_context(
                    &home,
                    &user_id.into(),
                    &org,
                    team.as_deref(),
                )
                .map(|binding| binding.for_caller(scope))
                .and_then(|binding| {
                    super::records_tools::run(&binding, operation, &params, &actor, index)
                }),
            )
        })
        .await
        .map_err(|e| ErrorData::internal_error(e, None))?;
        match result {
            Ok(value) => envelope_json(&super::tool_envelope::ToolEnvelope::Ok(value)),
            Err(message) => {
                envelope_json(&super::tool_envelope::ToolEnvelope::<()>::Validation { message })
            }
        }
    }

    /// Which org's notes a notes tool works on, and where they live: the org the
    /// caller names, else the org its session works in (a remote session's bound
    /// workspace, or the org open in the app). `Err` is the reply to send instead.
    async fn notes_location(
        &self,
        org: Option<String>,
    ) -> Result<Result<(commands::notes_history::NotesLocation, String), CallToolResult>, ErrorData>
    {
        let named = org.map(|o| o.trim().to_string()).filter(|o| !o.is_empty());
        let (home, user_id, org) = match &self.remote_authority {
            Some(authority) => {
                let ctx = authority.context().await?;
                (
                    ctx.codesense_home,
                    ctx.user_id,
                    named.unwrap_or(ctx.org_slug),
                )
            }
            None => {
                let (home, user_id) = commands::route_to_context::resolve_ambient(&self.app_handle)
                    .await
                    .map_err(|m| ErrorData::invalid_params(m, None))?;
                let org = match named {
                    Some(org) => org,
                    None => match commands::route_to_context::derive_active_context(
                        &self.app_handle,
                    )
                    .await
                    {
                        Ok(ctx) => ctx.org_slug,
                        Err(_) => return Ok(Err(envelope_json(&tool_envelope::ToolEnvelope::<
                            (),
                        >::Validation {
                            message:
                                "no org is open in CodeSense: pass `org` (see list_orgs_teams)"
                                    .to_string(),
                        })?)),
                    },
                };
                (home, user_id, org)
            }
        };
        let located = commands::await_blocking("mcp.notes_location", {
            let org = org.clone();
            move || Ok::<_, String>(commands::scratch::org_notes_location(&home, user_id, &org))
        })
        .await
        .map_err(|e| ErrorData::internal_error(e, None))?;
        match located {
            Ok(loc) => Ok(Ok((loc, org))),
            Err(message) => Ok(Err(envelope_json(
                &tool_envelope::ToolEnvelope::<()>::Validation { message },
            )?)),
        }
    }

    /// Credit writes to the verified connection, including captured remote sessions.
    async fn notes_actor(
        &self,
        session_id: Option<&str>,
    ) -> Result<commands::notes_history::NoteActor, ErrorData> {
        use commands::notes_history::NoteActor;
        let credited = |me: super::identity_tools::WhoAmI| {
            NoteActor::agent(&me.display_name, me.session_id, Some(me.handle))
                .with_avatar(me.avatar)
        };
        let session = self.own_session(session_id)?;
        match super::identity_tools::who_am_i(&self.app_handle, &session).await {
            Ok(me) => Ok(credited(me)),
            Err(_) if self.remote_authority.is_some() => {
                let handle = self.connection_session().unwrap_or_else(|| session.clone());
                Ok(NoteActor::agent(
                    &handle,
                    Some(session),
                    Some(handle.clone()),
                ))
            }
            Err(error) => Err(ErrorData::invalid_params(error, None)),
        }
    }

    /// Run a notes read and send its envelope.
    async fn notes_reply<T, F>(
        &self,
        label: &'static str,
        org: Option<String>,
        body: F,
    ) -> Result<CallToolResult, ErrorData>
    where
        T: Serialize + Send + 'static,
        F: FnOnce(&commands::notes_history::NotesLocation, &str) -> notes_tools::Reply<T>
            + Send
            + 'static,
    {
        let (loc, org) = match self.notes_location(org).await? {
            Ok(found) => found,
            Err(reply) => return Ok(reply),
        };
        let envelope = commands::await_blocking(label, move || body(&loc, &org))
            .await
            .map_err(|e| ErrorData::internal_error(e, None))?;
        envelope_json(&envelope)
    }

    /// Run a notes write credited to the caller, tell open notes views, and send
    /// its envelope.
    async fn notes_change<F>(
        &self,
        label: &'static str,
        org: Option<String>,
        session_id: Option<String>,
        body: F,
    ) -> Result<CallToolResult, ErrorData>
    where
        F: FnOnce(
                &commands::notes_history::NotesLocation,
                &str,
                &commands::notes_history::NoteActor,
            ) -> Result<
                (
                    tool_envelope::ToolEnvelope<notes_tools::NoteWritten>,
                    Option<notes_tools::Change>,
                ),
                String,
            > + Send
            + 'static,
    {
        let actor = self.notes_actor(session_id.as_deref()).await?;
        let (loc, org) = match self.notes_location(org).await? {
            Ok(found) => found,
            Err(reply) => return Ok(reply),
        };
        let notes_dir = loc.notes_dir();
        let (envelope, change, org, actor) = commands::await_blocking(label, move || {
            body(&loc, &org, &actor).map(|(envelope, change)| (envelope, change, org, actor))
        })
        .await
        .map_err(|e| ErrorData::internal_error(e, None))?;
        if let Some(change) = change {
            let path = notes_dir.join(format!("{}.md", change.id));
            commands::frontmatter_editor::note_written(
                &self.app_handle,
                &path.to_string_lossy(),
                &path,
            );
            commands::notes_history::emit_notes_changed(
                &self.app_handle,
                Some(&org),
                &change.id,
                change.commit.as_deref(),
                &actor,
                change.kind,
            );
        }
        envelope_json(&envelope)
    }

    async fn dispatch_local_setup(
        &self,
        tool: &str,
        args: serde_json::Value,
    ) -> Result<CallToolResult, ErrorData> {
        let home = commands::paths::codesense_home_dir()
            .ok_or_else(|| invalid_err(tool, "cannot resolve home directory"))?;
        let scope = self.caller_scope().await;
        let principal = commands::local_profile::active(&self.app_handle)
            .map_err(|e| invalid_err(tool, e))?
            .principal;
        let value = super::local_setup::dispatch_for(
            &self.app_handle,
            &home,
            &principal,
            tool,
            args,
            &scope,
        )
        .await
        .map_err(|e| invalid_err(tool, e))?;
        ok_json(value)
    }

    fn attachment_state(
        &self,
    ) -> Result<
        (
            Arc<crate::content_engine::sync::WaveCoordinator>,
            tauri::State<'_, super::state::ActiveTeamState>,
        ),
        ErrorData,
    > {
        let coord = self
            .app_handle
            .try_state::<Arc<crate::content_engine::sync::WaveCoordinator>>()
            .ok_or_else(|| ErrorData::internal_error("wave coordinator unavailable", None))?
            .inner()
            .clone();
        let active_team = self
            .app_handle
            .try_state::<super::state::ActiveTeamState>()
            .ok_or_else(|| ErrorData::internal_error("active team state unavailable", None))?;
        Ok((coord, active_team))
    }

    fn admit_local_setup_mutation(&self, tool: &str) -> Result<(), ErrorData> {
        super::local_setup::admit(tool).map_err(|e| ErrorData::invalid_params(e, None))
    }

    async fn context(&self) -> Result<ActiveContext, ErrorData> {
        match &self.remote_authority {
            Some(authority) => authority.context().await,
            None => derive_active_context(&self.app_handle).await,
        }
    }

    /// Switch the app's active team the way a team click does: run the
    /// backend team activation (watchers, content waves, connector reload,
    /// `ActiveTeamState`), then tell the UI to show the team.
    async fn switch_active_team(
        &self,
        params: setup_tools::SetActiveTeamParams,
    ) -> Result<tool_envelope::ToolEnvelope<setup_tools::ActiveTeamSwitched>, ErrorData> {
        // Every path that moves the user's view passes the same gate, including
        // a move/copy's explicit `org` scope.
        crate::commands::interactive_gate::InteractiveGate::admit("set_active_team")
            .map_err(gate_err)?;
        let (home, user_id) = commands::route_to_context::resolve_ambient(&self.app_handle)
            .await
            .map_err(|m| ErrorData::invalid_params(m, None))?;
        self.switch_active_team_for_profile(home, user_id, params)
            .await
    }

    async fn switch_active_team_for_profile(
        &self,
        home: std::path::PathBuf,
        user_id: u64,
        params: setup_tools::SetActiveTeamParams,
    ) -> Result<tool_envelope::ToolEnvelope<setup_tools::ActiveTeamSwitched>, ErrorData> {
        self.admit_local_setup_mutation("set_active_team")?;
        let app = self.app_handle.clone();
        let reply = setup_tools::set_active_team(home, user_id, params, |activation| async move {
            commands::content_engine::set_active_team_for_wave(
                app,
                activation.codesense_home.to_string_lossy().into_owned(),
                activation.user_id,
                activation.org_slug,
                activation.team,
                activation.source_repos,
            )
            .await
        })
        .await
        .map_err(|e| ErrorData::internal_error(e, None))?;
        if let tool_envelope::ToolEnvelope::Ok(switched) = &reply {
            setup_tools::emit_active_team_switch(&self.app_handle, switched);
        }
        Ok(reply)
    }

    /// The move/copy `org` scope: switch into `(org, team)` or refuse the op.
    async fn switch_into_scope(&self, org: &str, team: &str) -> Result<(), ErrorData> {
        match self
            .switch_active_team(setup_tools::SetActiveTeamParams {
                org: org.to_string(),
                team: team.to_string(),
            })
            .await?
        {
            tool_envelope::ToolEnvelope::Ok(_) => Ok(()),
            tool_envelope::ToolEnvelope::Validation { message } => {
                Err(ErrorData::invalid_params(message, None))
            }
            _ => Err(ErrorData::invalid_params(
                format!("{org}:{team} is not a team you can switch to (see describe_setup)"),
                None,
            )),
        }
    }

    /// Commit one team-registry edit for the active local profile (see `team_tools`).
    async fn commit_team_edit(
        &self,
        (org, edit): (String, crate::context_repo::RegistryEdit),
    ) -> Result<CallToolResult, ErrorData> {
        let (home, user_id) = commands::route_to_context::resolve_ambient(&self.app_handle)
            .await
            .map_err(|m| ErrorData::invalid_params(m, None))?;
        let reply = team_tools::commit_team_edit(
            &self.app_handle,
            &home,
            &Principal::from(user_id),
            &org,
            edit,
        )
        .await
        .map_err(|e| ErrorData::internal_error(e, None))?;
        envelope_json(&reply)
    }

    /// The router this server serves: the `#[tool]` registrations, with object-rooted
    /// input schemas and the long descriptions that live beside their params.
    pub(crate) fn served_tool_router() -> ToolRouter<Self> {
        let mut router = Self::tool_router();
        // The publish verbs exist only in the `dashboard-publish` build.
        #[cfg(feature = "dashboard-publish")]
        router.merge(Self::publish_tool_router());
        // MCP tool arguments have an object root, and strict clients reject
        // the whole tools/list response when a schema leaves out that root
        // type, so every root says `type: object`. A root must never be a
        // union (the Anthropic API refuses a top-level anyOf/oneOf/allOf):
        // a tool with several forms takes one flat params struct and picks
        // its form after decoding. Nothing here strips unions; a test over
        // the served list holds every tool to it.
        for route in router.map.values_mut() {
            let schema = std::sync::Arc::make_mut(&mut route.attr.input_schema);
            schema.insert("type".into(), serde_json::json!("object"));
            super::schema_inline::inline_refs(schema).unwrap_or_else(|e| {
                panic!(
                    "served tool `{}` input schema could not be inlined: {e}",
                    route.attr.name
                )
            });
        }
        // The full query_context description (model + examples) lives
        // beside its params so they change together.
        if let Some(route) = router.map.get_mut("query_context") {
            route.attr.description = Some(super::context_query_tool::DESCRIPTION.into());
        }
        if let Some(route) = router.map.get_mut("codesense_overview") {
            route.attr.description = Some(super::overview::DESCRIPTION.into());
        }
        if let Some(route) = router.map.get_mut("who_am_i") {
            route.attr.description = Some(super::identity_tools::WHO_AM_I_DESCRIPTION.into());
        }
        if let Some(route) = router.map.get_mut("feedback_send") {
            route.attr.description = Some(super::feedback_tool::DESCRIPTION.into());
        }
        // The release a tool needs is told from its CLI's descriptor, never restated.
        for route in router.map.values_mut() {
            if let Some(filled) = route.attr.description.as_deref().and_then(with_releases) {
                route.attr.description = Some(filled.into());
            }
        }
        // The viewer state's fields are told with the two tools that use them, so
        // the server instructions stay within what a client keeps.
        for name in ["get_viewer_state", "set_viewer_state"] {
            if let Some(route) = router.map.get_mut(name) {
                let base = route.attr.description.take().unwrap_or_default();
                route.attr.description = Some(format!("{base}\n\n{VIEWER_STATE_FIELDS}").into());
            }
        }
        for (name, route) in router.map.iter_mut() {
            if let Some(family) = super::reference::family(name) {
                let base = route.attr.description.as_deref().unwrap_or("");
                // Replace any old pointer so the final line has exactly one target.
                let body = base
                    .lines()
                    .filter(|line| !line.starts_with("Docs: "))
                    .collect::<Vec<_>>()
                    .join("\n");
                route.attr.description =
                    Some(format!("{}\nDocs: {}", body.trim_end(), family.docs).into());
            }
        }
        router
    }

    /// Resolve the contexts dir through the shared, non-creating resolver in
    /// `commands::system`. Routing every reader through one resolver (rather
    /// than re-deriving the path here) is what keeps the MCP view from drifting
    /// onto a stale directory when the bundle identifier changes.
    fn contexts_dir(&self) -> Option<PathBuf> {
        crate::commands::system::contexts_dir_path(&self.app_handle).ok()
    }

    fn repo_count(&self) -> usize {
        self.contexts_dir().map(|d| count_repos_in(&d)).unwrap_or(0)
    }

    /// Load the active org for the authoring tools, so the "what's
    /// configured for this org" resolution has exactly one home. Shared by
    /// `list_source_repos` (which reads `.teams`) and `validate_story` (which
    /// also borrows the whole `Org` as the assignee roster — one
    /// `load_org` call, no double disk read). Reads the working-tree registry
    /// (`remote_url = None`); a missing/partial org yields `None`, which the
    /// callers surface as an empty pick-list / skipped roster rather than an
    /// error.
    fn load_org_for_authoring(&self, ctx: &ActiveContext) -> Option<crate::domain::Org> {
        let org_root = crate::context_repo::path_to_org_root(
            &ctx.codesense_home,
            &ctx.principal(),
            &ctx.org_slug,
        )
        .ok()?;
        crate::domain::load_org(ctx.org_slug.clone(), &org_root, None).org
    }

    /// The shared move/copy body — a thin typed adapter over the merged
    /// `move_content_between_contexts` spine. Runs the gate ladder (via the
    /// shared `context_mobility` core, so UI/MCP resolve the identical gates in the
    /// identical order), returning the FIRST unmet gate as a typed `{ status:
    /// "gate", reason }`; on success it wraps the merged outcome. A COPY sets
    /// `retain_source`; neither a move nor a copy has a sole-copy gate. The
    /// only behavioral difference between the two tools is the `op`.
    async fn run_context_mobility(
        &self,
        op: commands::context_mobility::MobilityOp,
        params: MoveBetweenContextsToolParams,
    ) -> Result<CallToolResult, ErrorData> {
        let scope = self.caller_scope().await;

        // An explicit `org` scope resolves the cross-org gate up front by
        // switching the active org before the op (the alternative to a prior
        // set_active_team call). Applied before deriving context so the derive sees
        // the switched org.
        if let Some(org) = params.org.as_deref() {
            let team = params
                .team
                .as_deref()
                .ok_or_else(|| ErrorData::invalid_params("org requires a team", None))?;
            let active = self
                .app_handle
                .try_state::<super::state::ActiveTeamState>()
                .and_then(|state| state.get());
            // Already there: the full activation (watchers, waves, connector
            // reload, a UI switch) would only redo what is in place.
            if !setup_tools::is_active_team(active.as_ref(), org, team) {
                self.switch_into_scope(org, team).await?;
            }
        }

        let ctx = derive_active_context(&self.app_handle).await?;
        let stamp = commands::move_between_contexts::share_stamp(&self.app_handle).await;
        run_context_mobility_for(ctx, op, params, stamp, scope).await
    }
}

/// Architecture: mutation authorization is unchanged; destination readbacks use the caller.
async fn run_context_mobility_for(
    ctx: ActiveContext,
    op: commands::context_mobility::MobilityOp,
    params: MoveBetweenContextsToolParams,
    stamp: Option<commands::move_between_contexts::ShareStamp>,
    scope: crate::context_repo::caller_scope::CallerScope,
) -> Result<CallToolResult, ErrorData> {
    use commands::context_mobility::{
        first_unmet_gate, resolve_collision_knobs, CollisionKnobs, GateFacts,
    };
    use commands::move_between_contexts::{
        move_between_contexts_for, resolve_endpoint_root, MoveBetweenContextsParams,
    };
    let from_ep = parse_context_endpoint(&params.from)?;
    let to_ep = parse_context_endpoint(&params.to)?;
    let readable = resolve_endpoint_root(
        &ctx.codesense_home,
        ctx.user_id,
        Some(&ctx.org_slug),
        &to_ep,
    )
    .is_none_or(|root| scope.allows(&root.join(&params.logical_name)));
    let result = async {
        let home = ctx.codesense_home.clone();
        let uid = ctx.user_id;
        let logical_name = params.logical_name.clone();
        // The same provenance the app's own Share / Copy records.
        let probe = MoveBetweenContextsParams {
            from: from_ep.clone(),
            to: to_ep.clone(),
            logical_name: logical_name.clone(),
            to_logical_name: None,
            user_id: uid,
            force: false,
            retain_source: matches!(op, commands::context_mobility::MobilityOp::Copy),
        };
        if !commands::move_between_contexts::source_admitted(
            &home,
            Some(&ctx.org_slug),
            &probe,
            &scope,
        ) {
            return ok_json(
                serde_json::json!({"status":"ok","outcome":{"kind":"rejectedSourceMissing"}}),
            );
        }

        // Resolve the fact the gate ladder needs OFF-thread: whether the target
        // already holds this logical id (collision). It reads the resolved endpoint
        // root — the same math the move spine uses — so the ladder decides against
        // the real on-disk state.
        let (target_collision, existing_names) = {
            let home = home.clone();
            let to_ep_c = to_ep.clone();
            let probe = MoveBetweenContextsParams {
                from: from_ep.clone(),
                to: to_ep.clone(),
                logical_name: logical_name.clone(),
                to_logical_name: None,
                user_id: uid,
                force: false,
                retain_source: matches!(op, commands::context_mobility::MobilityOp::Copy),
            };
            let stamp = stamp.clone();
            let logical = logical_name.clone();
            let active_org = ctx.org_slug.clone();
            let scope = scope.clone();
            commands::await_blocking("mcp.mobility.facts", move || {
                // Does the target already hold this logical id? And the full name
                // set for a Keep-both rename search — both from the same resolved
                // root the move spine uses.
                let target_root =
                    resolve_endpoint_root(&home, uid, Some(active_org.as_str()), &to_ep_c);
                let existing: std::collections::HashSet<String> = target_root
                    .as_ref()
                    .and_then(|r| {
                        commands::context_mobility::list_context_items_for(r, &scope).ok()
                    })
                    .map(|items| items.into_iter().map(|i| i.logical_name).collect())
                    .unwrap_or_default();
                // A target already holding exactly what this op writes (a retry
                // of one that landed) is the op done, not a collision.
                let collision = existing.contains(&logical)
                    && !commands::move_between_contexts::target_already_holds(
                        &home,
                        Some(active_org.as_str()),
                        &probe,
                        stamp.as_ref(),
                    );
                Ok::<_, String>((collision, existing))
            })
            .await
            .map_err(|e| ErrorData::internal_error(e, None))?
        };

        let facts = GateFacts {
            op,
            from: &params.from,
            to: Some(&params.to),
            target_collision,
            confirm_make_shared: params.confirm_make_shared,
            // A move or copy never gates on a sole copy (the item lands somewhere).
            allow_sole_copy: false,
            policy_supplied: params.policy.is_some(),
        };
        if let Some(reason) = first_unmet_gate(&facts) {
            return gate_response(reason);
        }

        // The ladder is satisfied — map the resolved collision policy onto the
        // merged spine's knobs through the pure `resolve_collision_knobs` seam.
        let mut to_logical_name = None;
        let mut force = false;
        let mut renamed_to = None;
        match resolve_collision_knobs(&logical_name, target_collision, params.policy, |c| {
            existing_names.contains(c)
        }) {
            CollisionKnobs::RenameTo(name) => {
                to_logical_name = Some(name.clone());
                renamed_to = Some(name);
            }
            CollisionKnobs::Force => force = true,
            CollisionKnobs::LeaveTargetAsIs => {
                return ok_json(serde_json::json!({
                    "status": "ok",
                    "outcome": { "kind": "rejectedTargetExists" }
                }));
            }
            CollisionKnobs::Proceed => {}
        }

        let move_params = MoveBetweenContextsParams {
            to_logical_name,
            force,
            ..probe
        };
        let active_org = ctx.org_slug.clone();
        let outcome = {
            let (home, move_params, active_org) =
                (home.clone(), move_params.clone(), active_org.clone());
            commands::await_blocking("mcp.move_between_contexts", move || {
                move_between_contexts_for(
                    &home,
                    Some(active_org.as_str()),
                    &move_params,
                    stamp.as_ref(),
                    &scope,
                )
            })
            .await
            .map_err(|e| ErrorData::internal_error(e, None))?
        };

        let outcome_value =
            serde_json::to_value(&outcome).map_err(|e| serialize_err("move outcome", e))?;
        let mut resp = serde_json::json!({ "status": "ok", "outcome": outcome_value });
        if let Some(name) = renamed_to {
            resp["renamedTo"] = serde_json::Value::String(name);
        }
        ok_json(resp)
    }
    .await;
    if readable {
        result
    } else {
        Err(ErrorData::internal_error(
            crate::context_repo::caller_scope::MISSING,
            None,
        ))
    }
}

/// The context paths a path-addressed tool writes (creates, edits, moves or
/// deletes), as its arguments name them.
trait WrittenPaths {
    fn written_paths(&self) -> Vec<PathBuf>;
}

impl WrittenPaths for ApplyCanvasParams {
    fn written_paths(&self) -> Vec<PathBuf> {
        vec![self.path.clone()]
    }
}

impl WrittenPaths for SetEpicReposParams {
    fn written_paths(&self) -> Vec<PathBuf> {
        vec![PathBuf::from(&self.epic_file_path)]
    }
}

impl WrittenPaths for DeleteContentFileParams {
    fn written_paths(&self) -> Vec<PathBuf> {
        vec![PathBuf::from(&self.path)]
    }
}

impl WrittenPaths for MoveContentFileParams {
    fn written_paths(&self) -> Vec<PathBuf> {
        vec![PathBuf::from(&self.from_path), PathBuf::from(&self.to_path)]
    }
}

/// Refuses a path-addressed write that lands in the all-orgs folder (only
/// copy/move/remove with context `all-orgs` write there, and they admit
/// allowlisted inert files only), or that a symlink carries into a scratch
/// space it does not name. Where a write lands is judged with symlinks
/// resolved, off the async executor. The first thing each such tool runs.
async fn refuse_scratch_writes(params: &impl WrittenPaths) -> Result<(), ErrorData> {
    let paths = params.written_paths();
    let refusal = commands::await_blocking("mcp.scratch_write_gate", move || {
        Ok(paths
            .iter()
            .find_map(|path| crate::context_repo::scratch_space::write_refusal(path, false)))
    })
    .await
    .map_err(|e| ErrorData::internal_error(e, None))?;
    match refusal {
        Some(message) => Err(ErrorData::invalid_params(message, None)),
        None => Ok(()),
    }
}

/// Parse an agent-supplied stable logical id into the writable
/// endpoint the merged spine resolves. A view-only or malformed id is a typed
/// `invalid_params` (never a silent wrong-place resolution).
fn parse_context_endpoint(
    id: &str,
) -> Result<commands::move_between_contexts::ContextEndpoint, ErrorData> {
    commands::context_mobility::parse_context_id(id).ok_or_else(|| {
        ErrorData::invalid_params(
            format!("'{id}' is not a movable context id (personal, all-orgs or a team context)"),
            None,
        )
    })
}

/// Render the FIRST unmet mobility gate as a `{ status: "gate", reason, ... }`
/// envelope. The typed `reason` + its named resolution let an agent build a
/// deterministic retry ladder. No banned internal word appears in the payload.
fn gate_response(
    reason: commands::context_mobility::GateReason,
) -> Result<CallToolResult, ErrorData> {
    let mut value = serde_json::to_value(&reason).map_err(|e| serialize_err("gate reason", e))?;
    if let serde_json::Value::Object(map) = &mut value {
        map.insert(
            "status".to_string(),
            serde_json::Value::String("gate".into()),
        );
    }
    ok_json(value)
}

/// The accounts `list_agent_accounts` returns: the attached ones, and the detached ones too
/// when asked.
fn listed_agent_accounts(
    profiles: Vec<crate::install::agent_account_store::AgentAccountProfile>,
    include_detached: bool,
) -> Vec<commands::agent_accounts::AgentAccountView> {
    profiles
        .into_iter()
        .filter(|profile| include_detached || profile.is_attached())
        .map(commands::agent_accounts::AgentAccountView::from)
        .collect()
}

/// A resolution as `resolve_agent_account` returns it. A refusal of a requested account
/// names it, so the caller can say which account failed.
fn resolution_with_request(
    resolved: commands::agent_accounts::AgentAccountResolutionView,
    requested_account_id: Option<String>,
) -> Result<serde_json::Value, ErrorData> {
    let refused = !resolved.spawn_eligible;
    let mut value = serde_json::to_value(resolved)
        .map_err(|error| ErrorData::internal_error(error.to_string(), None))?;
    if let (true, Some(requested), Some(fields)) =
        (refused, requested_account_id, value.as_object_mut())
    {
        fields.insert("requestedAccountId".into(), requested.into());
    }
    Ok(value)
}

fn agent_provider(
    value: &str,
) -> Result<crate::install::agent_account_store::AgentProvider, ErrorData> {
    crate::install::agent_account_store::AgentProvider::parse(value)
        .ok_or_else(|| ErrorData::invalid_params("unknown agent account provider", None))
}

/// Count the immediate subdirectories of `dir` — each registered context repo
/// is one subdir. Returns 0 when the dir is missing or unreadable. Kept free
/// of the `AppHandle` so it can be unit-tested directly against a tempdir.
fn count_repos_in(dir: &Path) -> usize {
    match std::fs::read_dir(dir) {
        Ok(entries) => entries
            .filter_map(|e| e.ok())
            .filter(|e| e.file_type().map(|ft| ft.is_dir()).unwrap_or(false))
            .count(),
        Err(_) => 0,
    }
}

/// Back the validator's `AssigneeResolver` seam with the loaded
/// `Org`, delegating to the `person_by_username` resolver so login
/// normalization stays single-sourced in `domain::org` (never re-derived in the
/// pure validator, where it could drift from the Rust/TS twins).
impl story_authoring::AssigneeResolver for crate::domain::Org {
    fn is_known_login(&self, login: &str) -> bool {
        // An empty roster carries no data to validate against — treat it as
        // "roster unavailable" and skip (return known), so a not-yet-populated
        // `people.yml` during org bootstrap doesn't flag every assignee. Matches
        // the `NoAssigneeResolver` fallback: the check degrades to "not checked",
        // never a false-positive drift finding.
        self.people.is_empty() || self.person_by_username(login).is_some()
    }

    fn is_known_person_id(&self, person_id: &str) -> bool {
        self.people.is_empty()
            || self
                .people
                .iter()
                .any(|person| person.id.as_str() == person_id)
    }
}

