    // -----------------------------------------------------------------
    // Authoring tools (3, read-only). Together they close the
    // authoring loop: orient (`get_story_format`) → get legal values
    // (`list_source_repos`) → verify + self-correct (`validate_story`).
    // All logic lives in the pure `super::story_authoring` module; these
    // wrappers only resolve active context and delegate. No mutation, no
    // `domain:*` event — they ride below the mutation gate.
    // -----------------------------------------------------------------

    #[tool(
        description = "Authoring entry point. Returns the decision-first contract for creating CodeSense content: whether you need frontmatter at all (most content is a plain doc and needs none), the full pipeline-story frontmatter schema (Markdown + HTML `cs:*` forms, with the closed `type`/`status` enums), the validate_story finding codes, and cross-refs to list_source_repos + validate_story. Call this first."
    )]
    fn get_story_format(&self) -> Result<CallToolResult, ErrorData> {
        // Resolve the effective summary headings from app-state (sync
        // reader — this is a sync handler) so the contract reflects THIS
        // install's config, not a hardcoded default.
        let summary_headings =
            crate::commands::system::read_configured_summary_headings(&self.app_handle);
        ok_json(story_authoring::story_format_payload(&summary_headings))
    }

    #[tool(
        description = "List legal legacy `source_repo` values plus structured canonical repository identities. `primary`/`byTeam` omit host-ambiguous owner/repo values; use `sourceRepoIdentities` for explicit provider, host, and remoteKey details, plus each repo's local clone: `attachment` (`attached` = bound to a checkout that exists, `missing` = bound but the checkout is gone, `unattached` = none) and `localPath`. Never invent a source_repo; resolve it here."
    )]
    async fn list_source_repos(&self) -> Result<CallToolResult, ErrorData> {
        let ctx = self.context().await?;
        let teams = self
            .load_org_for_authoring(&ctx)
            .map(|o| o.teams)
            .unwrap_or_default();
        let team_repos: Vec<(String, Vec<String>)> = teams
            .iter()
            .map(|t| (t.name.clone(), unambiguous_story_repos(t)))
            .collect();
        let team_repo_identities: Vec<(String, Vec<(String, String)>)> = teams
            .iter()
            .map(|team| {
                (
                    team.name.clone(),
                    team.source_repos
                        .iter()
                        .map(|repo| (repo.to_string(), repo.remote_key()))
                        .collect(),
                )
            })
            .collect();
        // Each repo's clone status checks the disk, so it is built off the
        // async executor.
        let source_repo_identities: Vec<serde_json::Value> = {
            let attachments_path = crate::context_repo::path_to_user_attachments_file(
                &ctx.codesense_home,
                &ctx.principal(),
            );
            let teams = teams.clone();
            commands::await_blocking("mcp.list_source_repos", move || {
                let attachments =
                    crate::context_repo::attachments_io::read_attachments(&attachments_path)
                        .unwrap_or_default();
                let bound_clones = commands::attachments::group_attachments_by_remote(&attachments);
                Ok(teams
                    .iter()
                    .flat_map(|team| {
                        let bound_clones = &bound_clones;
                        team.source_repos.iter().map(move |repo| {
                            let clone = setup_tools::describe_repo(repo, bound_clones);
                            serde_json::json!({
                                "team": team.name,
                                "slug": repo.to_string(),
                                "provider": repo.provider,
                                "host": repo.canonical_host(),
                                "remoteKey": repo.remote_key(),
                                "attachment": clone.attachment,
                                "localPath": clone.local_path,
                            })
                        })
                    })
                    .collect())
            })
            .await
            .map_err(|e| ErrorData::internal_error(e, None))?
        };
        let active_team = ctx.team_name.clone().unwrap_or_default();
        let mut payload =
            story_authoring::source_repos_payload(&ctx.org_slug, &active_team, &team_repos);

        // Additively expose each repo's bound GitHub account
        // (or null) so a downstream PR-opening agent can pick the right
        // identity. Best-effort — a read failure just omits the mapping.
        let account_by_repo_key = resolve_bound_accounts(&self.app_handle, &ctx).await;
        if let Some(obj) = payload.as_object_mut() {
            obj.insert(
                "accountsByRepo".to_string(),
                serde_json::to_value(story_authoring::resolve_repo_accounts(
                    &team_repo_identities,
                    &account_by_repo_key,
                ))
                .unwrap_or(serde_json::Value::Null),
            );
            obj.insert(
                "sourceRepoIdentities".to_string(),
                serde_json::json!(source_repo_identities),
            );
        }
        ok_json(payload)
    }

    #[tool(
        description = "Validate a candidate CodeSense file BEFORE writing it. Pass `path` (preferred — anchors depends_on/supporting_docs checks) and/or inline `content`. Detects intent (plain_doc | pipeline_story | epic_main_doc) and never nags a plain doc. For a story, returns blocking + advisory findings ({code, field, severity, message, hint}) computed with the same parser + source_repo/type rules the pipeline cache uses. Never returns valid:true for a file it could not fully evaluate."
    )]
    async fn validate_story(
        &self,
        Parameters(params): Parameters<ValidateStoryParams>,
    ) -> Result<CallToolResult, ErrorData> {
        validate_story_request(
            &self.app_handle,
            self.connection_session().as_deref(),
            self.remote_team().map(Into::into),
            params,
        )
        .await
    }

    // -----------------------------------------------------------------
    // Low-level team-content tools (`sense_sync_*`). Each wraps a
    // `commands::content_engine` function; `derive_active_context` resolves
    // codesense_home / user_id / org_slug / team_name from app singletons so
    // the caller only supplies CWD-derivable inputs. CodeSense ships no skill
    // on top of them: users write their own sync skill on the explicit tools
    // (hydrate_worktree, reverse_sync_worktree, route_file_to_context, …).
    //
    // Soft rejections (`MoveOutcome::Rejected*`, `WriteOutcome::Rejected*`)
    // are returned as success-with-payload so the caller can branch on the
    // discriminator. Only hard failures (the typed boundary `Error`) surface as
    // MCP errors.
    // -----------------------------------------------------------------

    #[tool(
        description = "Adopt a file into team content — write `content` to `logicalName` in team content (`targetLayer`: \"TeamProjection\", the only layer). Only that team file changes: nothing is copied into any workspace (an agent gets it at its next launch if its context declares it, or by hydrate_worktree). Pass `expectedLayerHash` to refuse overwriting a team file that changed. To publish edits made in a workspace, prefer preview_reverse_sync_worktree then reverse_sync_worktree."
    )]
    async fn sense_sync_adopt(
        &self,
        Parameters(params): Parameters<SenseSyncAdoptParams>,
    ) -> Result<CallToolResult, ErrorData> {
        let ctx = self.context().await?;
        let scope = self.caller_scope().await;
        let value = super::context_tools::adopt_for(ctx, params, &scope, || {
            commands::content_engine::resolve_suppression_handle(&self.app_handle)
        })
        .await?;
        ok_json(value)
    }

    #[tool(
        description = "Route file to context — adopt a worktree file into the team content layer AND hide it from git (`.git/info/exclude`). An explicit adopt — CodeSense never adopts worktree files into team content on its own. Idempotent; returns an `outcome` discriminator (`routed` / `alreadyRouted` / `refused` / `collision` / `alreadyTracked` / `notProjectable`); a `layer` other than team content (the retired `TeamRepo`) is refused as invalid params."
    )]
    async fn route_file_to_context(
        &self,
        Parameters(params): Parameters<RouteFileToContextParams>,
    ) -> Result<CallToolResult, ErrorData> {
        use crate::commands::route_to_context::{run_route_for, RouteOutcomeDto};
        use crate::content_engine::layers::LayerId;
        // Delegate to the shared orchestration (`run_route_for`) so the
        // MCP tool and the Tauri command run ONE code path (derive ctx → resolver
        // ctx → per-repo lock → spawn_blocking the route core). This tool only maps
        // the outcome to the `{ "outcome": … }` JSON the skill expects.
        let caller = self.caller_scope().await;
        let outcome = run_route_for(
            &self.app_handle,
            params.code_repo_path,
            params.code_repo_slug,
            params.logical_name,
            params.layer.unwrap_or(LayerId::TeamProjection),
            caller,
        )
        .await
        .map_err(route_error_to_mcp)?;

        let value = serde_json::to_value(RouteOutcomeDto::from(&outcome))
            .map_err(|e| serialize_err("route outcome", e))?;
        ok_json(value)
    }

    #[tool(
        description = "Hydrate story — copy a story's epic context (its epic dir, or the closure a policy names) from team content into a workspace, on This Mac or a machine. Pass target:{kind:\"local\",codeRepoPath,sessionId} (your $PWD and $CODESENSE_TAB_SESSION_ID) or {kind:\"remote\",machineId,workspaceHandle} (your own, from who_am_i or list_sessions; or the handle prepare_remote_workspace returned), storyId, and an optional closure policy {referenceDepth, ancestryLevels, siblingBreadth, maxMembers}. Forward only: it never takes the workspace's edits back into team content (reverse_sync_worktree does that), and a file you edited is kept as it is. One comparison and one batched copy; the copies are hidden from git and recorded as managed. Optional operationId (UUID): calling again with it returns the kept result. Progress arrives as agent-prepare-progress events with that operationId; cancel_context_operation stops it. Returns status (ready/failed/cancelled), written/unchanged/kept counts, a note and the story's epicDir. Optional context:{kind:\"team\"} (default, your clone), {kind:\"worktree\",id} (a registered context checkout in the same org), or {kind:\"launcher\"} (the launching session’s captured launcherContext). A context choice never moves git refs. Worktrees are listed by list_worktrees {kind:\"context\"}."
    )]
    async fn hydrate_story(
        &self,
        Parameters(params): Parameters<super::context_operations::explicit::HydrateStoryParams>,
    ) -> Result<CallToolResult, ErrorData> {
        ok_json(
            super::context_operations::explicit::run(
                self.app_handle.clone(),
                params.target,
                params.context,
                super::context_operations::explicit::Op::Story {
                    story_id: params.story_id,
                    policy: params.policy,
                },
                params.operation_id,
                self.remote_authority.clone(),
                self.connection_session(),
            )
            .await?,
        )
    }

