    #[tool(
        description = "Move a file between content layers. Returns a MoveOutcome discriminator; a target that already exists is refused, never overwritten. With one layer left (team content) there is rarely a move to make; to rename a team file call move_content_file. Nothing is copied into any workspace."
    )]
    async fn sense_sync_move_layer(
        &self,
        Parameters(params): Parameters<SenseSyncMoveLayerParams>,
    ) -> Result<CallToolResult, ErrorData> {
        let ctx = derive_active_context(&self.app_handle).await?;
        let move_params = commands::content_engine::MoveFileParams {
            from_layer: params.from_layer,
            to_layer: params.to_layer,
            logical_name: params.logical_name,
            code_repo_slug: Some(params.code_repo_slug),
            codesense_home: ctx.codesense_home.to_string_lossy().into_owned(),
            user_id: ctx.user_id,
            org_slug: ctx.org_slug,
            team_name: ctx.team_name,
            // Single-file move today. To promote a whole skill subtree in
            // one call, set `move_as_subtree: true` and pass the skill
            // directory's logical-name prefix as `logical_name`; the move
            // primitive moves every leaf atomically under one lock. Left
            // off here until the Push UX opts into subtree promotion.
            move_as_subtree: false,
            conflict_policy: commands::content_engine::ConflictPolicy::RejectWhole,
            // Push never overwrites — a target collision rejects
            // (`RejectedTargetExists`), preserving today's behavior. The
            // force-overwrite path is opt-in (workbench "Replace").
            force: false,
        };
        let outcome = commands::content_engine::move_file_between_layers(
            self.app_handle.clone(),
            move_params,
        )
        .await
        .map_err(engine_err_to_mcp)?;
        ok_json(serde_json::to_value(&outcome).unwrap_or(serde_json::Value::Null))
    }

    #[tool(
        description = "Write worktree config — persist a source repo's worktree.yaml to the canonical codesense location. Resolves org_root from the active org (not passed in); derives the owner/repo slug from the repo's `origin` remote. Validates the YAML before writing and never writes inside the source repo. Inputs: repoPath (the source repo's path) + yaml (the full worktree.yaml document). Returns {writtenPath}."
    )]
    async fn write_worktree_config(
        &self,
        Parameters(params): Parameters<WriteWorktreeConfigParams>,
    ) -> Result<CallToolResult, ErrorData> {
        // org_root from active-org state — the skill cannot compute it (it
        // has no frontend); this is how it gets one. Shared with the read
        // verb via `derive_active_org_root`.
        let (org_root, authority) = derive_active_worktree_context(&self.app_handle).await?;

        // git2 (slug derivation) + filesystem write are blocking — offload
        // off the async reactor so nothing stalls the event loop.
        let repo_path = params.repo_path;
        let yaml = params.yaml;
        let written = tokio::task::spawn_blocking(move || {
            commands::worktree::write_worktree_config_with_authority(
                &repo_path, &org_root, &authority, &yaml,
            )
        })
        .await
        .map_err(|e| task_join_err("write", e))?
        .map_err(|e| ErrorData::invalid_params(e, None))?;

        ok_json(serde_json::json!({ "writtenPath": written.to_string_lossy() }))
    }

    #[tool(
        description = "Read worktree config — load a source repo's worktree.yaml from the canonical codesense location, falling back to the legacy in-repo `.codesense/worktree.yaml` during the transition window. Resolves org_root from the active org (not passed in); derives the owner/repo slug from the repo's `origin` remote. Input: repoPath (the source repo's path). Returns {config}: the parsed worktree.yaml as JSON, or null when no config exists at either location."
    )]
    async fn read_worktree_config(
        &self,
        Parameters(params): Parameters<ReadWorktreeConfigParams>,
    ) -> Result<CallToolResult, ErrorData> {
        // org_root from active-org state — identical resolution to the write
        // verb (shared `derive_active_org_root`); the skill has no frontend.
        let (org_root, authority) = derive_active_worktree_context(&self.app_handle).await?;

        // git2 (slug derivation) + filesystem read are blocking — offload off
        // the async reactor so the read never stalls the event loop. The core
        // owns canonical-first/legacy-fallback; no path logic is duplicated here.
        let repo_path = params.repo_path;
        let config = tokio::task::spawn_blocking(move || {
            commands::worktree::read_worktree_config_with_authority(
                &repo_path, &org_root, &authority,
            )
        })
        .await
        .map_err(|e| task_join_err("read", e))?
        .map_err(|e| ErrorData::invalid_params(e, None))?;

        // `config` is `Option<WorktreeConfig>` (Serialize) — serializes to the
        // parsed object or JSON null.
        ok_json(serde_json::json!({ "config": config }))
    }

    #[tool(
        description = "Remove a machine workspace whose folder is gone from the unsaved-team-edits list. Re-counts first and refuses unless it is still missing. Deletes no files, folders or branches on the machine: clears only that path's stale ownership marker and prunes Git's record so the story can be opened there again. Takes machineId and workspaceHandle from get_sync_status's remote target. Returns {status: removed} or {status: refused, state, reason}. A disconnected machine is never dialled; older terminal servers must be updated first."
    )]
    async fn forget_missing_workspace(
        &self,
        Parameters(target): Parameters<super::team_file_edits::ForgetMissingTarget>,
    ) -> Result<CallToolResult, ErrorData> {
        let ctx = derive_active_context(&self.app_handle).await?;
        let result =
            super::team_file_edits::forget_missing_workspace(&self.app_handle, ctx, target)
                .await
                .map_err(|e| ErrorData::invalid_params(e, None))?;
        ok_json(result)
    }

    #[tool(
        description = "Sync status: {setupState, recentOperations, unpublished}. setupState lists the active org's story worktrees ({codeRepoPath, storyId, intendedTeam, setupComplete}; setupComplete is true once the worktree's setup — worktree.yaml — has finished). recentOperations lists the explicit context operations (hydrate_worktree, hydrate_story, reverse_sync_worktree) running now and the latest finished ones, each {operationId, kind, state: running|ready|failed|cancelled, target, startedAtMs, finishedAtMs, result summary}. unpublished: team files changed inside the active team's workspaces and not back in the team yet, like unsaved changes — {total, cleanWorkspaces, workspaces:[{target, name, state, reason?, counts, files:[{path, kind: changed|new|removed|conflict|cannotPublish, destination:{kind: team|parentTeam|private|repo|other}, changedAtMs?, reason?, workspaceHash?, teamHash?, teamPath (the team file it publishes to, on this Mac), discardable?}], lastChangedAtMs?, checkedAtMs, fresh (counted on this call, else the last count as old as checkedAtMs), machineOnline?, machineName?, cwd?}], machineWorkspaces:[{target, name, machineOnline, checkedAtMs?}] (every machine workspace of the team, clean ones too)} (or {error} when it couldn't be read). Only workspaces with edits, or not counted cleanly, are listed; state is checked, notChecked, offline (machine not connected: its last count), unfinishedCopy (an earlier copy there never finished; not counted), missing (a completed workspace whose folder no longer exists; use forget_missing_workspace to remove its entry), or unknown (reason says why). Missing folders add no edits to total. Workspaces on this Mac are counted on every call. A machine workspace shows its last count from this session; pass target:{kind:\"remote\",machineId,workspaceHandle} (your own, from who_am_i or list_sessions) (from list_hydrated or this list) to count it now — one read-only call, never to a disconnected machine. CodeSense's own local and generated files (.claude/settings.local.json, .mcp.json, merged launch files) and repo-tracked files are never listed. When you finish a task, settle the team-file edits you made in your workspace: publish with reverse_sync_worktree (preview_reverse_sync_worktree first), undo a copied file's edits with hydrate_worktree {paths, overwriteModified:true}, delete new files you don't want; on a conflict (the team file changed too) tell the user. Read-only. Optional context selects only the destination of new files; copied files are counted against their recorded sources, named in each row’s contexts. Accepts {kind:\"team\"}, {kind:\"worktree\",id}, or {kind:\"launcher\"}; omission uses your clone."
    )]
    async fn get_sync_status(
        &self,
        Parameters(params): Parameters<SyncStatusParams>,
    ) -> Result<CallToolResult, ErrorData> {
        let scope = self.caller_scope().await;
        let ctx = derive_active_context(&self.app_handle).await?;
        let home = ctx.codesense_home.clone();
        let uid = ctx.user_id;
        let org = ctx.org_slug.clone();

        // `iter_records` is blocking fs — offload off the async reactor so the
        // status read never stalls the event loop (same posture as the
        // worktree-config verbs).
        let receipt_scope = scope.clone();
        let (records, recent) = tokio::task::spawn_blocking(move || {
            let principal = Principal::from(uid);
            let records = crate::install::worktree_index::iter_story_records(&home, &principal);
            let recent = super::context_operations::explicit::recent_for(
                &home,
                &principal,
                20,
                &receipt_scope,
            );
            (records, recent)
        })
        .await
        .map_err(|e| task_join_err("status", e))?;
        let records = records.map_err(|e| {
            ErrorData::internal_error(format!("worktree index read failed: {e}"), None)
        })?;

        let mut selected = crate::commands::content_engine::derive_resolver_context(
            ctx.codesense_home.clone(),
            ctx.user_id,
            ctx.org_slug.clone(),
            ctx.team_name.clone(),
        )
        .map_err(super::context_operations::invalid)?;
        let session = params.target.as_ref().map_or_else(
            || self.connection_session(),
            |target| target.context_session(self.connection_session()),
        );
        let launcher = session.and_then(|id| {
            self.app_handle
                .try_state::<commands::dashboard_launch::DashboardLaunchState>()
                .and_then(|s| s.launcher_context(&id))
        });
        super::context_operations::bind_context(&mut selected, params.context, launcher.as_deref())
            .map_err(super::context_operations::invalid)?;
        let refresh = match params.target {
            None => super::team_file_edits::Refresh::None,
            Some(super::context_operations::WorkspaceTarget::Local { code_repo_path, .. }) => {
                super::team_file_edits::Refresh::Local(code_repo_path)
            }
            Some(super::context_operations::WorkspaceTarget::Remote {
                machine_id,
                workspace_handle,
            }) => super::team_file_edits::Refresh::Remote {
                machine_id,
                handle: workspace_handle,
            },
        };
        let asked = !matches!(refresh, super::team_file_edits::Refresh::None);
        // A failed count never hides the rest of the status: it is reported
        // in `unpublished.error`; only a bad explicit `target` is the
        // caller's error.
        let unpublished = match super::team_file_edits::unpublished_context_for(
            &self.app_handle,
            ctx,
            refresh,
            selected.context_root,
            scope,
        )
        .await
        {
            Ok(value) => value,
            Err(e) if asked => return Err(ErrorData::invalid_params(e, None)),
            Err(e) => serde_json::json!({ "error": e }),
        };
        let mut payload = sync_status_payload(records, &org, recent);
        payload["unpublished"] = unpublished;
        ok_json(payload)
    }

    #[tool(
        description = "Publish workspace edits back to team content — the only way a workspace's changes reach the team. Pass target:{kind:\"local\",codeRepoPath,sessionId} or {kind:\"remote\",machineId,workspaceHandle}. Candidates are the files CodeSense copied into the workspace (each maps its original tier and path into the chosen context; the destination is checked against the copied baseline) plus new files under the workspace's declared context (they go to the active team, or to the tier `to` names: team, repo, personal). Optional paths:[files or folders] limits it; sets:[folders] also looks for new files there. A team file that changed since it was copied, or a new file whose team path already holds other bytes, is a conflict: it is never written, and comes back in conflicts. Team content is never deleted unless you pass includeDeletes:true: then a managed file removed in the workspace is removed from the team, only while the team still holds what was copied (without it such files come back in withheldRemovals). Files over 4 MiB are skipped. Batched: on a machine one manifest call and one streamed read of the changed files (plus one exclude-block batch when new files are added), then one all-or-nothing team write (each file compare-and-swapped; a race rolls back what this publish wrote). Call preview_reverse_sync_worktree first to see exactly what it will do. Optional operationId (UUID) makes a retry return the kept result. Returns status (published/publishedWithConflicts/nothingToPublish/failed/cancelled), entries [{path, action, targetLayer, targetPath}], conflicts, skipped, failed, withheldRemovals. Compatibility: kind:selected with requestId and items:[{op:update,path,ref,expectedSource,expectedWorkspace}] publishes those paths with those expected hashes; the scope-less {codeRepoPath, sessionId} form publishes every candidate. All forms are one flat object: `kind` picks the selected form, a scope-less field the scope-less form, anything else the target form. Optional context:{kind:\"team\"} (default, your clone), {kind:\"worktree\",id} (a registered context checkout in the same org), or {kind:\"launcher\"} (the launching session’s captured launcherContext). A context choice never moves git refs. Worktrees are listed by list_worktrees {kind:\"context\"}."
    )]
    async fn reverse_sync_worktree(
        &self,
        Parameters(params): Parameters<ReverseSyncWorktreeToolParams>,
    ) -> Result<CallToolResult, ErrorData> {
        use super::context_operations::explicit::{run, Op, PublishParams};
        let (params, expect) = match params.into_request()? {
            SelectedPublishRequest::Explicit(params) => (params, Default::default()),
            SelectedPublishRequest::Selected(params) => params.into_explicit()?,
            SelectedPublishRequest::Legacy(params) => (
                PublishParams {
                    context: params.context.clone(),
                    target: params.into_target(),
                    paths: Vec::new(),
                    sets: Vec::new(),
                    to: None,
                    include_deletes: false,
                    operation_id: None,
                },
                Default::default(),
            ),
        };
        ok_json(
            run(
                self.app_handle.clone(),
                params.target,
                params.context,
                Op::Publish {
                    paths: params.paths,
                    sets: params.sets,
                    to: params.to,
                    include_deletes: params.include_deletes,
                    expect,
                },
                params.operation_id,
                self.remote_authority.clone(),
                self.connection_session(),
            )
            .await?,
        )
    }

    #[tool(
        description = "Preview a publish read-only: exactly what reverse_sync_worktree would write to team content, with the same inputs (target, optional paths, sets, to). On a machine it is one manifest call. Returns entries [{path, action: add|update|remove, targetLayer, targetPath, bytes}], conflicts (never written: the team changed since the copy, or a new file's team path is taken), skipped (tracked by the repo, excluded, symlinks, over 4 MiB), unchanged, and withheldRemovals (team files a publish would only remove with includeDeletes:true; pass includeDeletes:true here to preview them as removals). Writes nothing. Compatibility: kind:selected with items:[{op:update,path,ref}], and the scope-less {codeRepoPath, sessionId} form. All forms are one flat object: `kind` picks the selected form, a scope-less field the scope-less form, anything else the target form. Optional context:{kind:\"team\"} (default, your clone), {kind:\"worktree\",id} (a registered context checkout in the same org), or {kind:\"launcher\"} (the launching session’s captured launcherContext). A context choice never moves git refs. Worktrees are listed by list_worktrees {kind:\"context\"}."
    )]
    async fn preview_reverse_sync_worktree(
        &self,
        Parameters(params): Parameters<PreviewReverseSyncParams>,
    ) -> Result<CallToolResult, ErrorData> {
        use super::context_operations::explicit::{run, Op, PreviewParams};
        let params = match params.into_request()? {
            SelectedPreviewRequest::Explicit(params) => params,
            SelectedPreviewRequest::Selected(params) => params.into_explicit(),
            SelectedPreviewRequest::Legacy(params) => PreviewParams {
                context: params.context.clone(),
                target: params.into_target(),
                paths: Vec::new(),
                sets: Vec::new(),
                to: None,
                include_deletes: false,
            },
        };
        ok_json(
            run(
                self.app_handle.clone(),
                params.target,
                params.context,
                Op::Preview {
                    paths: params.paths,
                    sets: params.sets,
                    to: params.to,
                    include_deletes: params.include_deletes,
                },
                None,
                self.remote_authority.clone(),
                self.connection_session(),
            )
            .await?,
        )
    }

    #[tool(
        description = "Hydrate a workspace from team content: copy the named files or context sets in, on This Mac or a machine. Pass target:{kind:\"local\",codeRepoPath,sessionId} (your $PWD and $CODESENSE_TAB_SESSION_ID) or {kind:\"remote\",machineId,workspaceHandle} (your own, from who_am_i or list_sessions), and paths:[exact files] and/or sets:[folders such as \"docs\" or \"docs\"]; with neither, the default agent context (CLAUDE.md, .claude/{runtime discovery folders}, AGENTS.md, native runtime folders). Forward only: it never publishes workspace edits. Additive: it adds missing files and refreshes ones nobody edited; prune:true also removes copies this workspace no longer wants under the paths/sets named (or the default context when none), never edited ones and never anything outside that scope. A file you edited (or one CodeSense didn't copy) is kept and reported; overwriteModified:true replaces it with the team's version (the Restore pinned files recovery). Files the repo tracks are never written. One comparison and one batched copy (on a machine: one manifest call and one batch); copies are hidden from git and recorded as managed. Optional operationId (UUID): calling again with it returns the kept result. Progress arrives as agent-prepare-progress events with that operationId; cancel_context_operation stops it, leaving no partial file. Returns status (ready/failed/cancelled), written/unchanged/kept/skipped counts with paths, and a note. Compatibility: kind:selected with requestId and items:[{ref:\"doc:<path>\"}] hydrates those paths; the scope-less {codeRepoPath, sessionId} form hydrates the default context. All forms are one flat object: `kind` picks the selected form, a scope-less field the scope-less form, anything else the target form. Optional context:{kind:\"team\"} (default, your clone), {kind:\"worktree\",id} (a registered context checkout in the same org), or {kind:\"launcher\"} (the launching session’s captured launcherContext). A context choice never moves git refs. Worktrees are listed by list_worktrees {kind:\"context\"}."
    )]
    async fn hydrate_worktree(
        &self,
        Parameters(params): Parameters<HydrateWorktreeParams>,
    ) -> Result<CallToolResult, ErrorData> {
        use super::context_operations::explicit::{run, HydrateParams, Op};
        let params = match params.into_request()? {
            SelectedHydrateRequest::Explicit(params) => params,
            SelectedHydrateRequest::Selected(params) => params.into_explicit()?,
            SelectedHydrateRequest::Legacy(params) => HydrateParams {
                context: params.context.clone(),
                target: params.into_target(),
                paths: Vec::new(),
                sets: Vec::new(),
                prune: false,
                overwrite_modified: false,
                operation_id: None,
            },
        };
        ok_json(
            run(
                self.app_handle.clone(),
                params.target,
                params.context,
                Op::Hydrate {
                    paths: params.paths,
                    sets: params.sets,
                    prune: params.prune,
                    overwrite_modified: params.overwrite_modified,
                },
                params.operation_id,
                self.remote_authority.clone(),
                self.connection_session(),
            )
            .await?,
        )
    }

    #[tool(
        description = "The state of one explicit context operation (hydrate_worktree, hydrate_story, reverse_sync_worktree) by its operationId (a selected request's requestId works too): {operationId, kind, state: running|ready|failed|cancelled, target, startedAtMs, finishedAtMs, result}. Read-only."
    )]
    async fn context_operation_status(
        &self,
        Parameters(params): Parameters<ContextOperationStatusParams>,
    ) -> Result<CallToolResult, ErrorData> {
        let id = match params.into_request()? {
            OperationStatusRequest::Operation(params) => params.operation_id,
            OperationStatusRequest::Selected(params) => {
                let _ = params.target;
                params.request_id
            }
        };
        let id = uuid::Uuid::parse_str(&id)
            .map_err(|_| ErrorData::invalid_params("operationId must be a UUID", None))?
            .to_string();
        let ctx = derive_active_context(&self.app_handle).await?;
        let principal = Principal::from(ctx.user_id);
        let scope = self.caller_scope().await;
        let found = super::context_operations::explicit::status_for(
            &ctx.codesense_home,
            &principal,
            &id,
            &scope,
        );
        match found {
            Some(record) => ok_json(serde_json::to_value(record).map_err(|e| {
                ErrorData::internal_error(format!("status serialize failed: {e}"), None)
            })?),
            None => ok_json(serde_json::json!({"operationId": id, "state": "unknown"})),
        }
    }

    #[tool(
        description = "Cancel a running explicit context operation (hydrate_worktree, hydrate_story, reverse_sync_worktree) by its operationId. A hydrate stops between files (locally) or before its Apply (on a machine): no partial file is left in the workspace, and the result says cancelled and lists what had already landed. A publish stops before it writes team content. Returns {operationId, cancelling: true} when it was running, else {cancelling: false, state}."
    )]
    async fn cancel_context_operation(
        &self,
        Parameters(params): Parameters<super::context_operations::explicit::OperationParams>,
    ) -> Result<CallToolResult, ErrorData> {
        let id = uuid::Uuid::parse_str(&params.operation_id)
            .map_err(|_| ErrorData::invalid_params("operationId must be a UUID", None))?
            .to_string();
        if super::context_operations::explicit::cancel(&id) {
            return ok_json(serde_json::json!({"operationId": id, "cancelling": true}));
        }
        let ctx = derive_active_context(&self.app_handle).await?;
        let state = super::context_operations::explicit::status(
            &ctx.codesense_home,
            &Principal::from(ctx.user_id),
            &id,
        )
        .map(|record| record.state)
        .unwrap_or_else(|| "unknown".into());
        ok_json(serde_json::json!({"operationId": id, "cancelling": false, "state": state}))
    }

    #[tool(
        description = "Apply canvas — validate + atomically write a shared Excalidraw canvas. Inputs: `path` (a target `.excalidraw` file on the codesense content rails, OR under a registered source-repo attachment / worktree for pre-release docs authoring) and `elements` (lightweight shape skeletons: `{type, x, y, width?, height?, text?, label?, points?, strokeColor?, backgroundColor?}`, where type ∈ rectangle|ellipse|diamond|text|line|arrow). Expands the skeletons into a full valid Excalidraw scene and writes it atomically — watcher-suppressed on the content rails (hot-reloads the open canvas), plain atomic write on a source-repo path (visible to `git status`). Whole-scene apply: the `elements` you pass become the ENTIRE scene. Malformed input is REJECTED before any write — fix and retry. Returns {writtenPath, elementCount}."
    )]
    async fn apply_canvas(
        &self,
        Parameters(params): Parameters<ApplyCanvasParams>,
    ) -> Result<CallToolResult, ErrorData> {
        refuse_scratch_writes(&params).await?;
        // Guard: only `.excalidraw` targets (case-insensitive). Path-rail
        // sandboxing (traversal / outside-every-allow-list) is enforced
        // downstream by `write_canvas_file`'s `validate_canvas_write_path_owned`.
        let path_str = params.path.to_string_lossy().into_owned();
        if !path_str.to_ascii_lowercase().ends_with(".excalidraw") {
            return Err(ErrorData::invalid_params(
                format!("path must be a .excalidraw file, got: {path_str}"),
                None,
            ));
        }

        // Validate + expand the skeletons into a full scene. A malformed call
        // is rejected HERE — invalid output never reaches disk. This is
        // a pure Rust action: no frontend round-trip, headless-capable.
        let scene = super::canvas_scene::build_scene(&params.elements)
            .map_err(|e| ErrorData::invalid_params(e, None))?;
        let element_count = params.elements.len();

        // Canvas-specific writer — context rails OR a registered
        // source-repo attachment / worktree. The context path is the live-edit
        // hot-reload path (watcher-suppressed); the source-repo path authors
        // `.excalidraw` sources into the pre-release docs tree.
        let app = self.app_handle.clone();
        let path_for_write = path_str.clone();
        commands::await_blocking("mcp.apply_canvas", move || {
            commands::files::write_canvas_file(&app, &path_for_write, &scene)
        })
        .await
        .map_err(|e| ErrorData::internal_error(format!("canvas write failed: {e}"), None))?;

        ok_json(serde_json::json!({ "writtenPath": path_str, "elementCount": element_count }))
    }

    #[tool(
        description = "Pane list — the custom right panes a team sees: the panes of every team in its chain (nearest first), then your private ones for that org. The same id in two places is two entries. Optional `org`+`team` (both, or neither for the active team). Returns { status:\"ok\", data:{ contentRoot (the content a pane's reads resolve against), panes:[{ id, scope (team|private), team?, title, icon?, path, panesDir, panelId, modified? }] } }, or `validation`, `unauthorizedTeam`, `notSyncedLocally`. Write one with pane_write, show one with pane_open; to delete a pane, delete its file. How to write a pane (the `window.codesense` SDK, theme, errors): see pane_write; full reference: get_live_data_contract."
    )]
    async fn pane_list(
        &self,
        Parameters(params): Parameters<pane_tools::PaneListParams>,
    ) -> Result<CallToolResult, ErrorData> {
        let scope = self.caller_scope().await;
        let target = tool_envelope::resolve_context(&self.app_handle, params.org, params.team)
            .await
            .map_err(|m| ErrorData::invalid_params(m, None))?;
        let ctx = match tool_envelope::resolved_or_envelope::<()>(target) {
            Ok(ctx) => ctx,
            Err(envelope) => return envelope_json(&envelope),
        };
        let Some(team) = ctx.team_name.clone() else {
            return envelope_json(&tool_envelope::ToolEnvelope::<()>::Validation {
                message: "no team: pass org and team".to_string(),
            });
        };
        routine_reply("mcp.pane_list", move || {
            pane_tools::list_for(
                &ctx.codesense_home,
                &ctx.principal(),
                &ctx.org_slug,
                &team,
                &scope,
            )
        })
        .await
    }

    #[tool(
        description = "Pane write — create or replace a custom right pane in ONE call: writes `html` to `<space>/panes/<id>.html` as a plain overwrite (no merge, no revision). Required: `id`, `html` (the whole document). Optional `scope`: `team` (default; `org`+`team`, or neither for the active team) or `personal` (your private space for `org`, which is then required; only when the user asks for a private pane). The pane appears in the right pane's Panels menu at once and an open one reloads; nothing is shared until your git push. Returns { status:\"ok\", data:{ id, scope, org, team?, path, panelId, created } } or `validation` (a bad id or scope, a team not synced here). Then pane_open shows it. A pane is ONE self-contained HTML file beside `content/` and `config/`, in a team space (the team and its child teams see it; teammates get it by git push like any team file) or your private space for an org (this Mac only). `id` matches [a-z0-9][a-z0-9-]*; the `<title>` is its label. Other files in `panes/` (e.g. `panes/lib/chart.js`) are never panes but load as relative assets (`<script src=\"lib/chart.js\">`). It renders in the right pane in an iframe with the same `window.codesense` SDK as an HTML dashboard: reads `codesense.queryContext(q)` (context files by metadata, resolved from the active team, so it sees the same stories a dashboard does), `codesense.sprints()`, `codesense.taxonomy()`; live updates `codesense.subscribeContext(q, (result, err) => ...)` (returns an unsubscribe); routine results `codesense.routineResult({id})`, `routineStatus`, `routineRefresh` (only on a user action), `onRoutineResult(cb)`; `codesense.readWorkspace(args)`; actions `codesense.act(verb, args)` (`openWorkspace`, `runPrompt`, `sendToSession`, ...; rate-guarded against runaway loops). Every call returns a Promise; a rejection carries the bridge's message unchanged (e.g. `unavailable: ...`) and is also echoed to the pane's error banner. Theme: the app sets its theme on the page root as CSS custom properties (`--cs-bg`, `--cs-fg`, `--cs-muted-fg`, `--cs-border`, `--cs-surface`, `--cs-accent`, `--cs-link`, `--cs-danger`, `--cs-success`, `--cs-warning`, `--cs-font-sans`) with `color-scheme` to match; style with them and keep the body background transparent, never `prefers-color-scheme` (the right pane can be dark while the app is light); `codesense.onTheme(cb)` fires on a change. Chrome: `<meta name=\"codesense:icon\" content=\"<lucide-name>\">` sets the panel icon, `codesense.setBadge({count, severity})` a title-bar count. `codesense.onVisibility(cb)` says when the pane is on screen (pause polling while hidden). `codesense.onIntent(cb)` receives the opaque intent from pane_open (a JSON object of at most 4096 UTF-8 bytes, interpreted only by the page); the host sends it after ready and the shim buffers the last one until a subscriber registers, then consumes it once; returns an unsubscribe. Agents: `codesense.sessions()` / `onSessions(cb)` list the live sessions, `act(\"stopSession\", {handle})` stops one, `codesense.agents()` lists the launchable agents. Errors are loud: a load failure, an uncaught error, a failed asset or an unhandled rejection shows a banner in the pane, never a blank pane. The page must call `codesense.ready()` once its first useful state is painted (after registering its handlers); a first `codesense.subscribe(...)` also counts (`subscribeContext` does not), else after 30 s the pane falls back (docs: your-first-dashboard, lifecycle-and-liveness). Saving the file reloads the pane within a second, keeping its scroll. Installed authoring references in the codesense/docs getting-started team: content/generated/pane-declaration.schema.json (declarations and manifest schema), content/generated/pane-declarations.md (HTML meta and YAML forms), content/generated/codesense.d.ts (exact SDK signatures), and content/generated/page-sdk.md. Full verb and argument reference: get_live_data_contract."
    )]
    async fn pane_write(
        &self,
        Parameters(params): Parameters<pane_tools::PaneWriteParams>,
    ) -> Result<CallToolResult, ErrorData> {
        let scope = self.caller_scope().await;
        let caller = routine_reader(&self.app_handle).await?;
        let target = match pane_target(
            &self.app_handle,
            params.scope.as_deref(),
            params.org,
            params.team,
        )
        .await
        {
            Ok(target) => target,
            Err(reply) => return reply,
        };
        routine_reply("mcp.pane_write", move || {
            pane_tools::write_for(
                &caller.home,
                &caller.principal,
                &target,
                &params.id,
                &params.html,
                &scope,
            )
        })
        .await
    }

    #[tool(
        description = "Pane open — place a custom right pane in the right pane and reveal it (opening the right pane if closed); it stays placed across restarts like a built-in panel. Required: `id` (from pane_list or pane_write). Optional `scope` (`team` default, or `personal`), `org`, `team`, as for pane_write. Optional `intent`: an opaque JSON object of at most 4096 UTF-8 bytes (larger objects return `validation`), forwarded to the page through codesense.onIntent(cb) once its shim is ready. A newer pending intent replaces an older one; delivered intents are not replayed on reload. A team pane shows while that team or a child team is active, a private one while its org is. Returns { status:\"ok\", data:{ panelId, path, placed } }: `placed` false (and `reason`) when the active team does not show that pane, so nothing was placed; the user must switch to its team. Or `validation` (no such pane). How to write a pane (the `window.codesense` SDK, theme, errors): see pane_write; full reference: get_live_data_contract."
    )]
    async fn pane_open(
        &self,
        Parameters(params): Parameters<pane_tools::PaneOpenParams>,
    ) -> Result<CallToolResult, ErrorData> {
        let caller = routine_reader(&self.app_handle).await?;
        let scope = self.caller_scope().await;
        let target = match pane_target(
            &self.app_handle,
            params.scope.as_deref(),
            params.org,
            params.team,
        )
        .await
        {
            Ok(target) => target,
            Err(reply) => return reply,
        };
        let active = self
            .app_handle
            .try_state::<super::state::ActiveTeamState>()
            .and_then(|state| state.get())
            .map(|team| (team.org_slug, team.team_name));
        let envelope = commands::await_blocking("mcp.pane_open", move || {
            pane_tools::open_for(
                &caller.home,
                &caller.principal,
                &target,
                &params.id,
                active
                    .as_ref()
                    .map(|(org, team)| (org.as_str(), team.as_str())),
                params.intent,
                &scope,
            )
        })
        .await
        .map_err(|e| ErrorData::internal_error(e, None))?;
        if let tool_envelope::ToolEnvelope::Ok(opened) = &envelope {
            if opened.placed {
                self.app_handle
                    .emit(crate::panes::PANE_OPEN_EVENT, opened)
                    .map_err(emit_err)?;
            }
        }
        envelope_json(&envelope)
    }

