    async fn workspace_group_tool(
        &self,
        action: &str,
        params: super::workspace_groups::GroupParams,
    ) -> Result<CallToolResult, ErrorData> {
        let active = self
            .app_handle
            .try_state::<super::state::ActiveTeamState>()
            .and_then(|s| s.get())
            .map(|t| format!("{}:{}", t.org_slug, t.team_name));
        let team = params
            .team_key
            .clone()
            .or_else(|| {
                self.remote_authority
                    .as_ref()
                    .map(|a| a.team_key().to_string())
            })
            .or(active);
        let Some(team) = team else {
            return ok_json(serde_json::json!({"status":"validation","message":"Unknown team."}));
        };
        let edit = serde_json::json!({"action":action,"groupId":params.group_id,"name":params.name,"workspaceIds":params.workspace_ids.unwrap_or_default(),"storyIds":params.story_ids.unwrap_or_default(),"workspaceId":params.workspace_id,"storyId":params.story_id});
        let app = self.app_handle.clone();
        let principal = crate::commands::local_profile::active(&app)
            .map_err(|e| ErrorData::internal_error(e, None))?
            .principal
            .to_string();
        let result = commands::await_blocking("workspace group edit", move || {
            super::workspace_groups::apply(&app, &team, edit, Some(&principal))
        })
        .await
        .map_err(|e| ErrorData::internal_error(e, None))?;
        ok_json(result)
    }

    /// Harness-only: the OPEN + RUN half of the round-trip through the
    /// REAL tool methods on THIS handler — `open_terminal_tab` →
    /// `run_in_terminal_tab` — plus the forged-target red path
    /// (`read_terminal_tab` against a handle that was never minted, which must be
    /// refused before any read). It calls the exact `#[tool]` method bodies the MCP
    /// transport dispatches (not a reimplementation, not the underlying
    /// `send_to_sessions`/`visible_text` seams directly), so the e2e proves the
    /// shipped verbs, not a bridge. Returns the opaque `handle` so the scenario can
    /// POLL the `read_terminal_tab` read (the `ls` output reaches the terminal
    /// asynchronously — a single immediate read would race the PTY). The forged
    /// path is decided here
    /// because it is timing-free (a bogus handle never resolves). Reachable only
    /// through the `CODESENSE_E2E`-gated Tauri command; nothing in production hits it.
    pub(crate) async fn e2e_terminal_open_run(
        &self,
        workspace_id: String,
    ) -> Result<E2eTerminalOpenRun, String> {
        // DETERMINISM: seed a temp dir holding ONE known marker file, then
        // run `ls <dir>` in the tab. The marker is a bare alnum+underscore token so
        // it survives the shell's echo/wrap escaping (the harness strips escapes the
        // same way) — a match in the scrollback proves real `ls` output, not a
        // placeholder. We own the seed here so the proof never depends on
        // whatever files a real cwd happens to hold.
        let marker = format!("SWWAF4_MARKER_{}", std::process::id());
        let seed_dir =
            std::env::temp_dir().join(format!("sw-wa-f4-{}-{}", std::process::id(), marker));
        std::fs::create_dir_all(&seed_dir).map_err(|e| format!("seed dir create failed: {e}"))?;
        std::fs::write(seed_dir.join(&marker), b"sw-wa-f4 round-trip marker\n")
            .map_err(|e| format!("seed marker write failed: {e}"))?;
        let command = format!("ls {}", seed_dir.display());

        // (1) open — the REAL `open_terminal_tab` verb. `headed:false` so the harness
        // never fights the window focus; the tab is still appended rightmost by construction.
        let opened = self
            .open_terminal_tab(Parameters(OpenTerminalTabParams {
                workspace_id: workspace_id.clone(),
                headed: Some(false),
                name: None,
            }))
            .await
            .map_err(|e| format!("open_terminal_tab failed: {}", err_message(&e)))?;
        let handle = tool_result_field(&opened, "handle")
            .ok_or_else(|| "open_terminal_tab returned no handle".to_string())?;

        //  forged-target red path FIRST — before any legitimate run/read has
        // happened — so the refusal can only be the anti-forgery boundary, never a
        // stale/consumed handle. A `read_terminal_tab` with a handle that was never
        // minted must be REFUSED trusted-side (it never resolves to a live session).
        let forged_handle = format!("forged-{}", handle);
        let forged_refusal = match self
            .read_terminal_tab(Parameters(ReadTerminalTabParams {
                since: None,
                handle: Some(forged_handle),
                tab: None,
                machine: None,
                workspace: None,
                view: None,
            }))
            .await
        {
            Ok(_) => None,
            Err(e) => Some(err_message(&e)),
        };

        // (2) run — the REAL `run_in_terminal_tab` verb: a shell line submitted
        // through the shipped settle→write→confirm shell-run gate into the tab's live PTY.
        self.run_in_terminal_tab(Parameters(RunInTerminalTabParams {
            handle: Some(handle.clone()),
            tab: None,
            machine: None,
            workspace: None,
            command: Some(command.clone()),
            key: None,
        }))
        .await
        .map_err(|e| format!("run_in_terminal_tab failed: {}", err_message(&e)))?;

        Ok(E2eTerminalOpenRun {
            handle,
            marker,
            forged_refused: forged_refusal.is_some(),
            forged_refusal: forged_refusal.unwrap_or_default(),
        })
    }

    /// Harness-only: the READ leg through the REAL tool method
    /// (`read_terminal_tab`) so the scenario can poll the tab's scrollback until the
    /// seeded marker appears (real PTY output is asynchronous). Same anti-forgery
    /// resolve + gate as every `read_terminal_tab` call; the harness passes the opaque handle
    /// `e2e_terminal_open_run` returned.
    pub(crate) async fn e2e_terminal_read(&self, handle: String) -> Result<String, String> {
        let read = self
            .read_terminal_tab(Parameters(ReadTerminalTabParams {
                handle: Some(handle),
                since: None,
                tab: None,
                machine: None,
                workspace: None,
                view: None,
            }))
            .await
            .map_err(|e| format!("read_terminal_tab failed: {}", err_message(&e)))?;
        Ok(tool_result_field(&read, "output").unwrap_or_default())
    }

