/// `get_viewer_state` inputs.
#[derive(Debug, Default, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct GetViewerStateParams {
    /// Only these parts: `localProfile`, `dependencies`, or viewer fields (`navLens`,
    /// `openTabs`, `terminalLayout`, `settings`, ...). Omitted: everything.
    #[serde(default)]
    pub sections: Option<Vec<String>>,
}

/// Whether a `get_viewer_state` call with `sections` asks for `name`.
fn viewer_section_wanted(sections: Option<&[String]>, name: &str) -> bool {
    Option::is_none_or(sections, |sections| {
        Iterator::any(&mut <[String]>::iter(sections), |section| section == name)
    })
}

/// `get_viewer_state`'s answer for `params`: `top` (app status) with `viewer`, the terminal
/// hosts' layouts read through `layouts` only when `terminalLayout` is asked for, then cut
/// to the asked sections. The served handler and its tests share this one path.
async fn viewer_state_response<Fut>(
    params: &GetViewerStateParams,
    mut top: serde_json::Value,
    mut viewer: serde_json::Value,
    layouts: impl FnOnce() -> Fut,
) -> serde_json::Value
where
    Fut: std::future::Future<Output = serde_json::Value>,
{
    let sections = Option::as_deref(&params.sections);
    if viewer_section_wanted(sections, "terminalLayout") {
        let layout = layouts().await;
        if let Some(fields) = serde_json::Value::as_object_mut(&mut viewer) {
            serde_json::Map::insert(fields, std::string::String::from("terminalLayout"), layout);
        }
    }
    super::nav_lens::external_sources(&mut viewer);
    top["viewer"] = viewer;
    viewer_state_answer(top, sections)
}

/// `response` (`get_viewer_state`'s full answer) cut to `sections`: `app_version` and
/// `repos_registered` always, `localProfile` and `dependencies` when named, and only the
/// named fields of `viewer`. A viewer that could not be read keeps its `error`. Names found
/// nowhere are listed once in `missingSections`.
fn viewer_state_answer(
    mut response: serde_json::Value,
    sections: Option<&[String]>,
) -> serde_json::Value {
    const ALWAYS: [&str; 2] = ["app_version", "repos_registered"];
    const TOP: [&str; 2] = ["localProfile", "dependencies"];
    let Some(sections) = sections else {
        return response;
    };
    let Some(fields) = serde_json::Value::as_object_mut(&mut response) else {
        return response;
    };
    for top in TOP {
        if !viewer_section_wanted(Some(sections), top) {
            serde_json::Map::remove(fields, top);
        }
    }
    let mut viewer_error = false;
    if let Some(viewer) = Option::and_then(
        serde_json::Map::get_mut(fields, "viewer"),
        serde_json::Value::as_object_mut,
    ) {
        viewer_error = serde_json::Map::contains_key(viewer, "error");
        serde_json::Map::retain(viewer, |key, _| {
            key == "error" || viewer_section_wanted(Some(sections), key)
        });
    }
    let mut missing: Vec<String> = std::vec::Vec::new();
    for section in sections {
        let name = std::string::String::as_str(section);
        let in_viewer = Option::and_then(serde_json::Map::get(fields, "viewer"), |viewer| {
            serde_json::Value::get(viewer, name)
        });
        let found = <[&str]>::contains(&ALWAYS, &name)
            || <[&str]>::contains(&TOP, &name)
            || Option::is_some(&in_viewer)
            || viewer_error;
        if !found && !<[String]>::contains(&missing, section) {
            std::vec::Vec::push(&mut missing, std::string::String::clone(section));
        }
    }
    if !std::vec::Vec::is_empty(&missing) {
        serde_json::Map::insert(
            fields,
            std::string::String::from("missingSections"),
            serde_json::Value::from(missing),
        );
    }
    response
}

