/// `wv_spawn_worker` inputs. An interactive verb: the caller passes the
/// two-seam interactive gate, which does not identify it.
#[derive(Debug, Deserialize, JsonSchema)]
pub struct WvSpawnWorkerParams {
    /// The story the worker works — also the roster PK (one live worker per story
    /// per scope). Resolved trusted-side to its managed worktree.
    pub story_id: String,
    /// The worker subclass: `impl` | `review` | `planning` | `research`. Each bakes
    /// its tool deny-list into the launch; every subclass gets the `codesense` bridge
    /// as its only MCP server.
    pub subclass: String,
    /// Optional first prompt seeded into the worker (e.g. a dispatch brief).
    #[serde(default)]
    pub initial_prompt: Option<String>,
    /// Optional agent provider (`claude` | `codex`). Absent → the team default
    /// (Claude). The ADK-neutral provider seam.
    #[serde(default)]
    pub provider: Option<String>,
    /// The scope to spawn under; only `"root"` is supported. Absent → `"root"`.
    #[serde(default)]
    pub scope: Option<String>,
}

impl WvSpawnWorkerParams {
    /// The spawn request for these inputs. The launcher is the caller's verified session and
    /// nothing a request can say: the inputs have no launcher of their own.
    pub(crate) fn into_request(
        self,
        subclass: crate::weft::WorkerSubclass,
        provider: Option<crate::install::agent_account_store::AgentProvider>,
        scope: String,
        verified_caller: Option<String>,
    ) -> crate::weft::WorkerSpawnRequest {
        crate::weft::WorkerSpawnRequest {
            story_id: self.story_id,
            subclass,
            initial_prompt: self.initial_prompt,
            provider,
            scope,
            // The MCP spawn verb carries no run correlation; the durable dispatch
            // bridge is the path that supplies a run_id.
            run_id: None,
            launched_by: verified_caller,
        }
    }
}

