/// `context_operation_status`'s input as one flat object: `{operationId}`,
/// or (compatibility) a selected request's `{target, requestId}`.
#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
pub(crate) struct ContextOperationStatusParams {
    /// The id an operation returned (or the `requestId` of a selected one).
    /// Required unless `target` and `requestId` are sent instead.
    #[serde(
        default,
        deserialize_with = "super::flat_params::present",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "String")]
    pub operation_id: Option<String>,
    /// Compatibility, with `requestId` instead of `operationId`: the
    /// selected request's workspace.
    #[serde(
        default,
        deserialize_with = "super::flat_params::present",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "super::context_operations::WorkspaceTarget")]
    pub target: Option<super::context_operations::WorkspaceTarget>,
    /// Compatibility, with `target`: the selected request's `requestId`.
    #[serde(
        default,
        deserialize_with = "super::flat_params::present",
        skip_serializing_if = "Option::is_none"
    )]
    #[schemars(with = "String")]
    pub request_id: Option<String>,
}

impl ContextOperationStatusParams {
    /// `{operationId}` when it is sent, else `{target, requestId}`.
    pub(crate) fn into_request(self) -> Result<OperationStatusRequest, ErrorData> {
        use super::flat_params::{refuse_extra, require};
        let Self {
            operation_id,
            target,
            request_id,
        } = self;
        if let Some(operation_id) = operation_id {
            refuse_extra(
                "operationId form",
                &[
                    ("target", target.is_some()),
                    ("requestId", request_id.is_some()),
                ],
            )
            .map_err(super::context_operations::invalid)?;
            return Ok(OperationStatusRequest::Operation(
                super::context_operations::explicit::OperationParams { operation_id },
            ));
        }
        const FORM: &str = "selected form";
        Ok(OperationStatusRequest::Selected(
            super::context_operations::StatusParams {
                target: require(FORM, "target", target)
                    .map_err(super::context_operations::invalid)?,
                request_id: require(FORM, "requestId", request_id)
                    .map_err(super::context_operations::invalid)?,
            },
        ))
    }
}

/// Decodes `value` through a tool's flat params and its form dispatch, and
/// checks the result against decoding the form enum directly: both accept
/// the same inputs and build the same form.
#[cfg(test)]
pub(crate) fn decode_via_flat<Flat, Form, E>(
    value: serde_json::Value,
    dispatch: fn(Flat) -> Result<Form, E>,
) -> Result<Form, String>
where
    Flat: serde::de::DeserializeOwned,
    Form: serde::de::DeserializeOwned + std::fmt::Debug,
    E: std::fmt::Debug,
{
    let direct = serde_json::from_value::<Form>(value.clone());
    let flat = serde_json::from_value::<Flat>(value.clone())
        .map_err(|e| e.to_string())
        .and_then(|flat| dispatch(flat).map_err(|e| format!("{e:?}")));
    match (&direct, &flat) {
        (Ok(direct), Ok(flat)) => assert_eq!(format!("{direct:?}"), format!("{flat:?}"), "{value}"),
        (Err(_), Err(_)) => {}
        _ => {
            panic!("flat and direct decoding disagree on {value}: direct {direct:?}, flat {flat:?}")
        }
    }
    flat
}

