pub struct WvRetireDecisionParams {
    /// The id of the decision to retire (set `status='superseded'`).
    pub id: i64,
}

#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct WvWriteApprovalParams {
    /// The PREFERRED endorsement tier: `T1` (pre-authorized), `T2` (lazy consent +
    /// window), `T3` (explicit 👍 required). The tier-picker may FORCE `T3` when two
    /// of {irreversible, high blast radius, low confidence} hold — a pre-declared
    /// `T3` is never downgraded. The stored `tier` is the picker's
    /// decision, returned in the response.
    #[serde(rename = "tier")]
    pub preferred_tier: String,
    /// Risk signal: the action cannot be undone. Defaults to `false`.
    #[serde(default)]
    pub irreversible: bool,
    /// Risk signal: `low` | `medium` | `high`. Defaults to `low`.
    #[serde(default = "default_blast_radius")]
    pub blast_radius: crate::weft::BlastRadius,
    /// Risk signal: `low` | `medium` | `high`. Defaults to `high`.
    #[serde(default = "default_confidence")]
    pub confidence: crate::weft::Confidence,
    /// What is being endorsed, in prose.
    pub claim: String,
    /// Optional source pointer (e.g. a test run or review for T3).
    #[serde(default)]
    pub source: Option<String>,
    /// T2 only: the revocation window — `open` | `paused` | an ISO-8601 expiry.
    /// Ignored for T1/T3.
    #[serde(default)]
    pub window_state: Option<String>,
    /// REQUIRED when the CHOSEN tier is `T3` (pre-declared OR picker-forced): the
    /// controller session to surface the question on — pass your
    /// `$CODESENSE_TAB_SESSION_ID`. Rejected if absent on a T3 outcome.
    #[serde(default)]
    pub session_id: Option<String>,
}

/// The low-risk default blast radius when a caller omits the signal —
/// keeps pre-E2 `wv_write_approval` callers classifying as low-risk (no
/// false-positive T3 escalation).
fn default_blast_radius() -> crate::weft::BlastRadius {
    crate::weft::BlastRadius::Low
}

/// The high-confidence default when a caller omits the signal.
fn default_confidence() -> crate::weft::Confidence {
    crate::weft::Confidence::High
}

/// Inputs to the read-only `wv_classify_action` verb. Mirrors the risk
/// signals of `wv_write_approval` but writes nothing — it returns the tier the
/// action WOULD enter plus the reasons that forced T3.
#[derive(Debug, Deserialize, JsonSchema)]
#[serde(rename_all = "camelCase")]
pub struct WvClassifyActionParams {
    /// A human-readable description of the action being classified (echoed for the
    /// agent's own logging; not persisted — this verb writes nothing).
    pub claim: String,
    /// Risk signal: the action cannot be undone. Defaults to `false`.
    #[serde(default)]
    pub irreversible: bool,
    /// Risk signal: `low` | `medium` | `high`. Defaults to `low`. An unrecognized
    /// value is a typed `invalid_params` error at the boundary.
    #[serde(default = "default_blast_radius")]
    pub blast_radius: crate::weft::BlastRadius,
    /// Risk signal: `low` | `medium` | `high`. Defaults to `high`. An unrecognized
    /// value is a typed `invalid_params` error at the boundary.
    #[serde(default = "default_confidence")]
    pub confidence: crate::weft::Confidence,
    /// The preferred tier (`T1` | `T2` | `T3`) used when the two-of-three rule does
    /// not force T3. A pre-declared `T3` is never downgraded.
    #[serde(rename = "preferredTier")]
    pub preferred_tier: String,
}

