    #[test]
    fn identity_tool_schemas_teach_optional_bound_sessions_and_unbound_refusal() {
        let router = super::CodesenseHandler::served_tool_router();
        for name in ["send_message", "reply", "read_messages", "signal_done"] {
            let tool = router.get(name).unwrap();
            let description = tool.description.as_deref().unwrap().to_lowercase();
            assert!(
                description.contains("unbound") && description.contains("codesense terminal"),
                "{name}"
            );
            let schema = serde_json::to_value(&tool.input_schema).unwrap();
            let required = schema["required"].as_array().cloned().unwrap_or_default();
            assert!(
                !required.contains(&serde_json::json!("sessionId"))
                    && !required.contains(&serde_json::json!("session_id")),
                "{name}"
            );
        }
    }

    #[test]
    fn initialize_meta_names_the_calling_tab() {
        use super::session_from_meta;
        use rmcp::model::Meta;
        let meta = |v: serde_json::Value| Meta(v.as_object().unwrap().clone());
        assert_eq!(
            session_from_meta(Some(&meta(
                serde_json::json!({"codesenseSessionId": " tab-1 "})
            ))),
            Some("tab-1".into())
        );
        assert_eq!(
            session_from_meta(Some(&meta(serde_json::json!({"codesenseSessionId": ""})))),
            None
        );
        assert_eq!(
            session_from_meta(Some(&meta(serde_json::json!({"codesenseSessionId": 3})))),
            None
        );
        assert_eq!(session_from_meta(Some(&meta(serde_json::json!({})))), None);
        assert_eq!(session_from_meta(None), None);
        // The bridge's wire shape parses into the request rmcp hands `initialize`.
        let request: rmcp::model::InitializeRequestParams =
            serde_json::from_value(serde_json::json!({
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "claude-code", "version": "1"},
                "_meta": {"codesenseSessionId": "tab-9"}
            }))
            .unwrap();
        assert_eq!(
            session_from_meta(request.meta.as_ref()),
            Some("tab-9".into())
        );
    }

    #[test]
    fn a_blank_inbox_list_session_id_names_no_session() {
        assert_eq!(super::inbox_list_session(None), None);
        assert_eq!(super::inbox_list_session(Some("")), None);
        assert_eq!(super::inbox_list_session(Some("  \t")), None);
        assert_eq!(super::inbox_list_session(Some(" s-1 ")), Some("s-1"));
    }

    #[test]
    fn role_pending_guard_sender_is_the_tab_whatever_sender_is_passed() {
        // An agent in a tab labelling itself "human" or a free label is still its tab,
        // so its routine's own run never re-fires the routine.
        assert_eq!(
            super::role_pending_guard_sender(Some("sess-run"), "human"),
            "sess-run"
        );
        assert_eq!(
            super::role_pending_guard_sender(Some(" sess-run "), "the reviewer"),
            "sess-run"
        );
        // Outside any tab the resolved sender stands.
        assert_eq!(super::role_pending_guard_sender(None, "human"), "human");
        assert_eq!(super::role_pending_guard_sender(Some("  "), "h-1"), "h-1");
    }

    #[test]
    fn initialize_meta_arrives_in_the_request_context_not_the_params() {
        // Over the wire rmcp moves `params._meta` into the request's extensions; the
        // handler must read the session from there.
        use super::session_from_meta;
        let msg: rmcp::model::ClientJsonRpcMessage = serde_json::from_value(serde_json::json!({
            "jsonrpc": "2.0", "id": 1, "method": "initialize",
            "params": {"protocolVersion": "2025-06-18", "capabilities": {},
                "clientInfo": {"name": "t", "version": "0"},
                "_meta": {"codesenseSessionId": "tab-9"}}
        }))
        .unwrap();
        let rmcp::model::ClientJsonRpcMessage::Request(req) = msg else {
            panic!("not a request")
        };
        use rmcp::model::GetMeta;
        let context_meta = req.request.get_meta().clone();
        assert_eq!(session_from_meta(Some(&context_meta)), Some("tab-9".into()));
    }

    /// The context's session wins; an empty params `_meta` never hides it, and the
    /// params copy is used only when the context names none.
    #[test]
    fn initialize_reads_the_context_session_before_the_params() {
        use super::initialize_session;
        let meta = |v: serde_json::Value| rmcp::model::Meta(v.as_object().unwrap().clone());
        let empty = meta(serde_json::json!({}));
        let tab = meta(serde_json::json!({"codesenseSessionId": "tab-9"}));
        let other = meta(serde_json::json!({"codesenseSessionId": "tab-2"}));
        assert_eq!(initialize_session(Some(&empty), &tab), Some("tab-9".into()));
        assert_eq!(initialize_session(Some(&other), &tab), Some("tab-9".into()));
        assert_eq!(initialize_session(Some(&tab), &empty), Some("tab-9".into()));
        assert_eq!(initialize_session(None, &empty), None);
    }

    /// A call naming the retired `TeamRepo` tier fails at
    /// the tool's parameter boundary (rmcp's own decode), and the MCP error a
    /// caller sees carries the pointer to `reverse_sync_worktree {to:"repo"}`.
    #[test]
    fn a_retired_team_repo_layer_reaches_the_caller_as_a_pointer() {
        use rmcp::handler::server::tool::parse_json_object;
        let object = |value: serde_json::Value| value.as_object().unwrap().clone();
        let adopt = parse_json_object::<SenseSyncAdoptParams>(object(serde_json::json!({
            "codeRepoPath": "/w",
            "codeRepoSlug": {"owner": "acme", "repo": "api"},
            "logicalName": "notes/a.md",
            "targetLayer": "TeamRepo",
            "content": "x",
        })))
        .unwrap_err();
        assert!(
            adopt.message.contains("reverse_sync_worktree"),
            "{}",
            adopt.message
        );
        let route = parse_json_object::<RouteFileToContextParams>(object(serde_json::json!({
            "codeRepoPath": "/w",
            "codeRepoSlug": {"owner": "acme", "repo": "api"},
            "logicalName": "notes/a.md",
            "layer": "TeamRepo",
        })))
        .unwrap_err();
        assert!(
            route.message.contains("reverse_sync_worktree"),
            "{}",
            route.message
        );
        // The old repo-agnostic name still decodes (as team content).
        let old = parse_json_object::<RouteFileToContextParams>(object(serde_json::json!({
            "codeRepoPath": "/w",
            "codeRepoSlug": {"owner": "acme", "repo": "api"},
            "logicalName": "notes/a.md",
            "layer": "TeamWorkspace",
        })))
        .unwrap();
        assert_eq!(
            old.layer,
            Some(crate::content_engine::layers::LayerId::TeamProjection)
        );
    }

    /// Every input form of the explicit operations parses onto the
    /// one engine: the target form (local and remote), the selected form and
    /// the scope-less legacy forms; mixed or unknown fields are refused.
    #[test]
    fn explicit_operation_inputs_remap_every_form_and_reject_mixed_targets() {
        use super::{
            decode_via_flat, HydrateWorktreeParams, PreviewReverseSyncParams,
            ReverseSyncWorktreeToolParams, SelectedHydrateRequest, SelectedPreviewRequest,
            SelectedPublishRequest,
        };
        let hydrate = |v| decode_via_flat(v, HydrateWorktreeParams::into_request);
        let publish = |v| decode_via_flat(v, ReverseSyncWorktreeToolParams::into_request);
        let preview = |v| decode_via_flat(v, PreviewReverseSyncParams::into_request);
        use crate::mcp::context_operations::explicit::{HydrateStoryParams, ListHydratedParams};
        use crate::mcp::context_operations::WorkspaceTarget;
        use serde_json::json;
        let remote = json!({"kind":"remote","machineId":"personal-machine","workspaceHandle":"remote-workspace-owned"});
        let local = json!({"kind":"local","codeRepoPath":"/local/worktree","sessionId":"s"});
        // The scope-less remote form IS the target form (default context).
        match hydrate(json!({"target":remote})).unwrap() {
            SelectedHydrateRequest::Explicit(params) => {
                assert!(params.paths.is_empty() && params.sets.is_empty() && !params.prune);
                assert!(matches!(params.target, WorkspaceTarget::Remote { .. }));
            }
            other => panic!("{other:?}"),
        }
        match hydrate(
            json!({"target":local,"sets":[".claude/skills"],"prune":true,"overwriteModified":true,"operationId":uuid::Uuid::new_v4().to_string()}),
        )
        .unwrap()
        {
            SelectedHydrateRequest::Explicit(params) => {
                assert_eq!(params.sets, vec![".claude/skills"]);
                assert!(params.prune && params.overwrite_modified);
            }
            other => panic!("{other:?}"),
        }
        // The scope-less local form.
        let legacy =
            hydrate(json!({"codeRepoPath":"/local/worktree","sessionId":"local-session"})).unwrap();
        let SelectedHydrateRequest::Legacy(legacy) = legacy else {
            panic!("legacy");
        };
        assert!(matches!(
            legacy.into_target(),
            WorkspaceTarget::Local { .. }
        ));
        // The selected form maps its doc: refs onto paths.
        let id = uuid::Uuid::new_v4().to_string();
        let SelectedHydrateRequest::Selected(selected) = hydrate(
            json!({"kind":"selected","requestId":id,"target":local,"items":[{"ref":"doc:docs/a.md"}]}),
        )
        .unwrap() else {
            panic!("selected");
        };
        let mapped = selected.into_explicit().unwrap();
        assert_eq!(mapped.paths, vec!["docs/a.md"]);
        assert_eq!(mapped.operation_id.as_deref(), Some(id.as_str()));
        let hash = format!("blake3:{}", blake3::hash(b"x").to_hex());
        let SelectedPublishRequest::Selected(selected_publish) = publish(
            json!({"kind":"selected","requestId":id,"target":remote,"items":[{"op":"update","path":"docs/a.md","ref":"doc:docs/a.md","expectedSource":{"kind":"hash","hash":hash},"expectedWorkspace":{"kind":"hash","hash":hash}}]}),
        )
        .unwrap() else {
            panic!("selected publish");
        };
        let (params, expect) = selected_publish.into_explicit().unwrap();
        assert_eq!(params.paths, vec!["docs/a.md"]);
        assert_eq!(
            expect["docs/a.md"].workspace,
            Some(*blake3::hash(b"x").as_bytes())
        );
        assert!(matches!(
            publish(json!({"target":remote,"to":"repo"})).unwrap(),
            SelectedPublishRequest::Explicit(_)
        ));
        // Every target-form field reaches the engine params.
        match publish(
            json!({"target":local,"paths":["docs/a.md"],"sets":["docs"],"to":"repo","includeDeletes":true,"operationId":id}),
        )
        .unwrap()
        {
            SelectedPublishRequest::Explicit(params) => {
                assert_eq!(params.paths, vec!["docs/a.md"]);
                assert_eq!(params.sets, vec!["docs"]);
                assert_eq!(params.to.as_deref(), Some("repo"));
                assert!(params.include_deletes);
                assert_eq!(params.operation_id.as_deref(), Some(id.as_str()));
            }
            other => panic!("{other:?}"),
        }
        assert!(matches!(
            publish(json!({"codeRepoPath":"/w","sessionId":"s"})).unwrap(),
            SelectedPublishRequest::Legacy(_)
        ));
        match preview(
            json!({"target":local,"paths":["docs/a.md"],"sets":["docs"],"to":"repo","includeDeletes":true}),
        )
        .unwrap()
        {
            SelectedPreviewRequest::Explicit(params) => {
                assert_eq!(params.paths, vec!["docs/a.md"]);
                assert_eq!(params.sets, vec!["docs"]);
                assert_eq!(params.to.as_deref(), Some("repo"));
                assert!(params.include_deletes);
            }
            other => panic!("{other:?}"),
        }
        assert!(matches!(
            preview(json!({"codeRepoPath":"/w","sessionId":"s"})).unwrap(),
            SelectedPreviewRequest::Legacy(_)
        ));
        assert!(matches!(
            preview(json!({"kind":"selected","target":local,"items":[{"op":"update","path":"docs/a.md","ref":"doc:docs/a.md"}]}))
                .unwrap(),
            SelectedPreviewRequest::Selected(_)
        ));
        // Status takes an operationId, or a selected request's target + requestId.
        let status = |v| decode_via_flat(v, super::ContextOperationStatusParams::into_request);
        assert!(matches!(
            status(json!({"operationId":id})).unwrap(),
            super::OperationStatusRequest::Operation(_)
        ));
        assert!(matches!(
            status(json!({"target":remote,"requestId":id})).unwrap(),
            super::OperationStatusRequest::Selected(_)
        ));
        for invalid in [
            json!({}),
            json!({"operationId":id,"target":remote}),
            json!({"operationId":id,"requestId":id}),
            json!({"target":remote}),
            json!({"requestId":id}),
            json!({"operationId":null}),
            json!({"operationId":id,"extra":true}),
        ] {
            assert!(status(invalid.clone()).is_err(), "{invalid}");
        }
        // A refusal names the field, as invalid params.
        let refusal = super::HydrateWorktreeParams::into_request(
            serde_json::from_value(json!({"kind":"selected","target":local,"items":[]})).unwrap(),
        )
        .unwrap_err();
        assert_eq!(refusal.code, rmcp::model::ErrorCode::INVALID_PARAMS);
        assert_eq!(refusal.message, "invalid: selected form requires requestId");
        let refusal = super::ReverseSyncWorktreeToolParams::into_request(
            serde_json::from_value(json!({"target":remote,"codeRepoPath":"/w","sessionId":"s"}))
                .unwrap(),
        )
        .unwrap_err();
        assert_eq!(refusal.code, rmcp::model::ErrorCode::INVALID_PARAMS);
        assert_eq!(
            refusal.message,
            "invalid: scope-less form does not take target"
        );
        // A null is never read as an absent field the form forbids.
        for invalid in [
            json!({"target":null,"codeRepoPath":"/w","sessionId":"s"}),
            json!({"kind":null,"target":remote}),
            json!({"target":remote,"prune":null}),
        ] {
            assert!(hydrate(invalid.clone()).is_err(), "{invalid}");
        }
        // hydrate_story and list_hydrated take either target.
        for target in [&remote, &local] {
            assert!(serde_json::from_value::<HydrateStoryParams>(
                json!({"target":target,"storyId":"STORY-1","policy":{"referenceDepth":1,"ancestryLevels":0,"siblingBreadth":false,"maxMembers":10}})
            )
            .is_ok());
            assert!(serde_json::from_value::<ListHydratedParams>(json!({"target":target})).is_ok());
        }
        for invalid in [
            json!({"target":remote,"codeRepoPath":"/local/worktree","sessionId":"local-session"}),
            json!({"target":remote,"codeRepoSlug":"owner/repo"}),
            json!({"target":{"kind":"remote","machineId":"machine","workspaceHandle":"handle","path":"/tmp"}}),
            json!({"target":{"kind":"local","machineId":"machine","workspaceHandle":"handle"}}),
            json!({"target":remote,"items":[{"ref":"doc:a"}]}),
        ] {
            assert!(hydrate(invalid.clone()).is_err(), "{invalid}");
        }
        // Each form refuses the other forms' fields, and a half-sent
        // scope-less form is refused rather than read as the target form.
        let publish_item = json!([{"op":"update","path":"docs/a.md","ref":"doc:docs/a.md","expectedSource":{"kind":"hash","hash":hash},"expectedWorkspace":{"kind":"hash","hash":hash}}]);
        for invalid in [
            json!({"kind":"selected","requestId":id,"target":remote,"items":publish_item,"to":"repo"}),
            json!({"kind":"selected","requestId":id,"target":remote,"items":publish_item,"includeDeletes":true}),
            json!({"kind":"selected","requestId":id,"target":remote,"items":publish_item,"operationId":id}),
            json!({"codeRepoPath":"/w"}),
            json!({"sessionId":"s"}),
        ] {
            assert!(publish(invalid.clone()).is_err(), "{invalid}");
        }
        let preview_item = json!([{"op":"update","path":"docs/a.md","ref":"doc:docs/a.md"}]);
        for invalid in [
            json!({"kind":"selected","target":local,"items":preview_item,"to":"repo"}),
            json!({"kind":"selected","target":local,"items":preview_item,"includeDeletes":true}),
            json!({"kind":"selected","requestId":id,"target":local,"items":preview_item}),
            json!({"target":local,"items":preview_item}),
            json!({"target":local,"operationId":id}),
        ] {
            assert!(preview(invalid.clone()).is_err(), "{invalid}");
        }
        assert!(hydrate(json!({"codeRepoPath":"/w"})).is_err());
        // A target-form operationId may be null; the selected form takes none.
        assert!(hydrate(json!({"target":local,"operationId":null})).is_ok());
        assert!(hydrate(
            json!({"kind":"selected","requestId":id,"target":local,"items":[{"ref":"doc:docs/a.md"}],"operationId":null})
        )
        .is_err());
        assert!(serde_json::from_value::<HydrateStoryParams>(
            json!({"target":remote,"storyId":"STORY-1","codeRepoPath":"/local/worktree"})
        )
        .is_err());
    }

