    /// The close guard emits on drop: the recorded end, nothing for a reply, and
    /// `cancelled` when the waiting future is dropped mid-wait.
    #[tokio::test]
    async fn a_dropped_ask_future_still_emits_ask_user_closed() {
        use std::time::Duration;
        use tokio_util::sync::CancellationToken;
        let (app, seen) = ask_closed_capture();
        app.manage(AskUserRegistry::new());
        let (registered, _reply) = app.state::<AskUserRegistry>().register("s1");
        assert!(app
            .state::<AskUserRegistry>()
            .pending_sessions()
            .contains("s1"));
        drop(AskClosedGuard::new(app.handle(), "s1", &registered));
        assert!(app.state::<AskUserRegistry>().pending_sessions().is_empty());
        seen.lock().unwrap().clear();

        {
            let mut g = AskClosedGuard::new(app.handle(), "s1", "ask-user-20");
            g.finish(AskEnd::TimedOut);
        }
        {
            let mut g = AskClosedGuard::new(app.handle(), "s1", "ask-user-21");
            g.finish(AskEnd::Replied);
        }

        let handle = app.handle().clone();
        let (started_tx, started_rx) = tokio::sync::oneshot::channel::<()>();
        let task = tokio::spawn(async move {
            let (id, rx) = handle.state::<AskUserRegistry>().register("s1");
            let mut closed = AskClosedGuard::new(&handle, "s1", &id);
            let _ = started_tx.send(());
            let (_, end) = await_ask_reply(
                rx,
                &CancellationToken::new(),
                Duration::from_secs(600),
                || {},
            )
            .await;
            closed.finish(end);
        });
        started_rx.await.unwrap();
        task.abort();
        assert!(task.await.unwrap_err().is_cancelled());
        assert!(app.state::<AskUserRegistry>().pending_sessions().is_empty());

        let got: Vec<(String, String)> = seen
            .lock()
            .unwrap()
            .iter()
            .map(|p| {
                (
                    p["correlationId"].as_str().unwrap().to_string(),
                    p["reason"].as_str().unwrap().to_string(),
                )
            })
            .collect();
        assert_eq!(
            got,
            vec![
                ("ask-user-20".to_string(), "timeout".to_string()),
                ("ask-user-1".to_string(), "cancelled".to_string()),
            ]
        );
    }

