    /// End to end over the wait: a cancelled and a timed-out wait each emit the
    /// close for their correlation; a reply emits none.
    #[tokio::test]
    async fn every_non_answer_end_of_a_wait_emits_ask_user_closed() {
        use std::time::Duration;
        use tokio_util::sync::CancellationToken;
        let (app, seen) = ask_closed_capture();

        let (_tx, rx) = tokio::sync::oneshot::channel::<AskUserOutcome>();
        let ct = CancellationToken::new();
        ct.cancel();
        let (_, end) = await_ask_reply(rx, &ct, Duration::from_secs(60), || {}).await;
        emit_ask_closed(app.handle(), "s1", "ask-user-7", end);

        let (_tx, rx) = tokio::sync::oneshot::channel::<AskUserOutcome>();
        let (_, end) = await_ask_reply(
            rx,
            &CancellationToken::new(),
            Duration::from_millis(5),
            || {},
        )
        .await;
        emit_ask_closed(app.handle(), "s1", "ask-user-8", end);

        let (tx, rx) = tokio::sync::oneshot::channel();
        tx.send(AskUserOutcome::accept("yes".into())).unwrap();
        let (_, end) = await_ask_reply(
            rx,
            &CancellationToken::new(),
            Duration::from_secs(60),
            || {},
        )
        .await;
        emit_ask_closed(app.handle(), "s1", "ask-user-9", end);

        let reasons: Vec<(String, String)> = seen
            .lock()
            .unwrap()
            .iter()
            .map(|p| {
                (
                    p["correlationId"].as_str().unwrap().to_string(),
                    p["reason"].as_str().unwrap().to_string(),
                )
            })
            .collect();
        assert_eq!(
            reasons,
            vec![
                ("ask-user-7".to_string(), "cancelled".to_string()),
                ("ask-user-8".to_string(), "timeout".to_string()),
            ]
        );
    }

    // ======================================================================
    // Consent in front of env-mutating signal_done hooks, and
    // the NO-SECOND-ORCHESTRATOR fold/write-path conformance grep.
    // ======================================================================

    /// A representative env-mutating hook on the `signal_done` host mutates
    /// ONLY after clearing the consent gate. With a present token it records exactly
    /// one mutation and no refusal; with a missing / blank token it records NO mutation
    /// AND a `ConsentRequired` refusal marker — the fail-closed branch is affirmatively
    /// observable, not inferred from the absence of a mutation. Proves the gate sits in
    /// front of the write; there is no production env-mutating hook to gate yet.
    #[test]
    fn env_mutating_hook_mutates_only_after_clearing_g1_consent() {
        // A fixture env-mutating hook body: it mutates a counter only when the consent gate
        // admits; otherwise it records the ConsentRequired refusal as its outcome.
        fn run_env_hook(
            action_kind: &str,
            consent_token: Option<&str>,
            mutations: &mut u32,
            refusals: &mut u32,
        ) -> EnvHookGate {
            match admit_env_mutating_hook(action_kind, consent_token) {
                EnvHookGate::Admitted => {
                    *mutations += 1;
                    EnvHookGate::Admitted
                }
                EnvHookGate::ConsentRequired => {
                    // Fail-closed: skip the mutation, record the refusal as an
                    // observable branch (not a silent no-op).
                    *refusals += 1;
                    EnvHookGate::ConsentRequired
                }
            }
        }

        // The kind is an already-shipped ENV_MUTATING_ACTIONS value (the fold/write path
        // does NOT extend the vocabulary with connector_write).
        let kind = "set_env";
        assert!(
            crate::weft::ENV_MUTATING_ACTIONS.contains(&kind),
            "the fixture uses an already-shipped env-mutating kind"
        );

        // No token → fail-closed: no mutation, one recorded refusal.
        let mut mutations = 0u32;
        let mut refusals = 0u32;
        let out = run_env_hook(kind, None, &mut mutations, &mut refusals);
        assert_eq!(out, EnvHookGate::ConsentRequired);
        assert_eq!(mutations, 0, "no mutation fires without consent");
        assert_eq!(refusals, 1, "the ConsentRequired refusal is observable");

        // Blank token → still fail-closed.
        let out = run_env_hook(kind, Some("   "), &mut mutations, &mut refusals);
        assert_eq!(out, EnvHookGate::ConsentRequired);
        assert_eq!(mutations, 0, "a blank token is not consent");
        assert_eq!(refusals, 2);

        // Present token → admitted: exactly one mutation, no new refusal.
        let out = run_env_hook(kind, Some("consent-xyz"), &mut mutations, &mut refusals);
        assert_eq!(out, EnvHookGate::Admitted);
        assert_eq!(mutations, 1, "the mutation proceeds with consent");
        assert_eq!(refusals, 2, "no refusal recorded on the admitted path");
    }

    /// The fold/write path does NOT extend `ENV_MUTATING_ACTIONS` — the exact
    /// already-shipped vocabulary is preserved.
    #[test]
    fn d3_does_not_extend_env_mutating_actions() {
        assert_eq!(
            crate::weft::ENV_MUTATING_ACTIONS,
            &["set_cwd", "set_env", "credential_write",],
            "D3 must not add a kind (e.g. connector_write)"
        );
        assert!(
            !crate::weft::ENV_MUTATING_ACTIONS.contains(&"connector_write"),
            "connector_write is C2's, never D3's"
        );
    }

    /// The NO-SECOND-ORCHESTRATOR conformance grep. The fold/write path
    /// — the `verify_done` stamp site, `close_task`/`resolve`, the fold verbs, and the
    /// `signal_done` hook host — introduces no standalone scheduler (`tokio::spawn` /
    /// `tokio::time::interval` / `std::thread::spawn` / `cron` / a dispatch `loop {`)
    /// around the gate calls. The gates are reached only through the existing controller
    /// verbs and the hook host, never a background loop and never the ratify reply path.
    #[test]
    fn no_second_orchestrator_on_the_fold_write_path() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
        // The fold/write gate call regions, scanned for scheduler primitives.
        let regions: &[(&str, &str, &str)] = &[
            // (file, region-start marker, region-end marker)
            (
                "src/weft/done_record.rs",
                "let result = VerifyDoneResult::ok();",
                "Ok(result)",
            ),
            (
                "src/weft/queue.rs",
                "let owner = claimed_by.as_deref().unwrap_or(\"\");",
                "Ok(Ok(()))",
            ),
            (
                "src/mcp/handler.rs",
                "pub(crate) fn admit_env_mutating_hook",
                "crate::weft::SignalDoneHooks::new()",
            ),
        ];
        const FORBIDDEN: &[&str] = &[
            "tokio::spawn",
            "tokio::time::interval",
            "std::thread::spawn",
            "cron",
        ];
        let mut violations = Vec::new();
        for (file, start_marker, end_marker) in regions {
            let src = std::fs::read_to_string(root.join(file)).expect("read source region");
            let start = src
                .find(start_marker)
                .unwrap_or_else(|| panic!("{file}: start marker {start_marker:?} present"));
            let rest = &src[start..];
            let end = rest
                .find(end_marker)
                .map(|e| start + e)
                .unwrap_or_else(|| panic!("{file}: end marker {end_marker:?} present"));
            let region = &src[start..end];
            for line in region.lines() {
                let trimmed = line.trim_start();
                if trimmed.starts_with("//") || trimmed.starts_with('*') {
                    continue;
                }
                let code = match line.find("//") {
                    Some(idx) => &line[..idx],
                    None => line,
                };
                for token in FORBIDDEN {
                    if code.contains(token) {
                        violations.push(format!("{file}: {}", line.trim()));
                    }
                }
                // A bare dispatch `loop {` on the fold/write path is also forbidden.
                if code.contains("loop {") {
                    violations.push(format!("{file}: {}", line.trim()));
                }
            }
        }
        assert!(
            violations.is_empty(),
            "NO-SECOND-ORCHESTRATOR: a scheduler primitive appeared on the D3 fold/write \
             path:\n{}",
            violations.join("\n")
        );
    }

    #[test]
    fn story_repo_ambiguity_is_scoped_to_each_team() {
        let github = crate::domain::SourceRepoSlug::new("acme", "api").unwrap();
        let gitlab = crate::domain::SourceRepoSlug::with_provider_and_host(
            "acme",
            "api",
            "gitlab",
            Some("gitlab.com"),
        )
        .unwrap();
        let github_team = crate::domain::Team::new("github-team", vec![github.clone()]).unwrap();
        let gitlab_team = crate::domain::Team::new("gitlab-team", vec![gitlab.clone()]).unwrap();

        assert_eq!(unambiguous_story_repos(&github_team), vec!["acme/api"]);
        assert_eq!(unambiguous_story_repos(&gitlab_team), vec!["acme/api"]);
        assert_eq!(
            story_authoring::configured_story_repos(&[github_team, gitlab_team]),
            vec!["acme/api"]
        );

        let ambiguous = crate::domain::Team::new("mixed", vec![github, gitlab]).unwrap();
        assert!(unambiguous_story_repos(&ambiguous).is_empty());
    }
    /// Auto-endorse has NO MCP surface to attack. The endorsement wall
    /// is absent from the rmcp tool registry entirely (not merely runtime-denied): neither
    /// the ratify (👍) verb NOR the endorse verb (nor any settle verb) is a registered tool,
    /// so a worker/controller MCP-context caller has no settle door to reach the wall. The
    /// tool_router is private to this module, so the proof lives here. Enumerating
    /// the REAL router (not a source grep) means a future `#[tool]` that accidentally
    /// exposed a settle verb reddens here.
    ///
    /// The forbidden verb names are CONSTRUCTED at runtime (`"wv_" + "ratify"`) so this test
    /// file does not itself contain the `wv_<ratify>` / `wv_<revoke>` literals the sibling
    /// ENDORSEMENT-WALL source-scan (`ratify_revoke_are_not_mcp_verbs`) forbids under src/mcp/.
    #[test]
    fn e1_no_settle_verb_is_a_registered_mcp_tool() {
        let router = CodesenseHandler::tool_router();
        // The owner's endorsement verbs — the ratify (👍) verb and the notional endorse
        // verb — are Tauri UI-boundary commands only, never MCP tools, so no agent can
        // self-endorse. (`wv_settle_approval` IS a sanctioned controller MCP verb — the
        // controller settles the paired approval — so it is NOT part of this wall; the wall
        // is specifically the human's ratify/endorse door.)
        let ratify = format!("wv_{}", "ratify");
        let endorse = format!("wv_{}", "endorse");
        for verb in [ratify.as_str(), endorse.as_str()] {
            assert!(
                !router.has_route(verb),
                "ENDORSEMENT-WALL (AC-7): `{verb}` must NOT be a registered MCP tool — \
                 ratify/endorse is a Tauri UI-boundary command only, never an MCP verb"
            );
        }
        // Positive control: the sanctioned agent path IS present — a worker POSTS its
        // pending assertion via `wv_post_assertion`; it just cannot SETTLE it. If this verb
        // vanished the "no surface" proof would be hollow.
        assert!(
            router.has_route("wv_post_assertion"),
            "the sanctioned post-assertion MCP verb must exist (else the AC-7 proof is hollow)"
        );
        // Self-check: the registry lookup is exact-name — a settle verb hiding as a
        // superstring of a real verb is NOT admitted (so the wall above cannot be defeated by a
        // `wv_<ratify>_v2`-style alias slipping through a substring check).
        assert!(
            !router.has_route("wv_post_assertion_but_also_ratify"),
            "the tool-registry check is exact-name (a superstring is not a route)"
        );
    }

    /// All a client is served for a tool: its description, then its input schema
    /// (where each parameter's own description is).
    pub(super) fn served_text(tool: &rmcp::model::Tool) -> String {
        format!(
            "{}\n{}",
            tool.description.as_deref().unwrap_or(""),
            serde_json::Value::Object((*tool.input_schema).clone())
        )
    }

