    /// Every schema node under `value` that is a JSON boolean where a schema is expected.
    fn boolean_schema_paths(value: &serde_json::Value, path: &str, out: &mut Vec<String>) {
        let schema_maps = ["properties", "patternProperties", "$defs", "definitions"];
        let schema_lists = ["anyOf", "oneOf", "allOf", "prefixItems"];
        let schema_slots = ["items", "additionalProperties", "not", "contains", "if", "then", "else"];
        let Some(object) = value.as_object() else {
            return;
        };
        for (key, child) in object {
            let here = format!("{path}.{key}");
            if schema_maps.contains(&key.as_str()) {
                for (name, schema) in child.as_object().into_iter().flatten() {
                    let at = format!("{here}.{name}");
                    if schema.is_boolean() {
                        out.push(at);
                    } else {
                        boolean_schema_paths(schema, &at, out);
                    }
                }
            } else if schema_lists.contains(&key.as_str()) {
                for (i, schema) in child.as_array().into_iter().flatten().enumerate() {
                    let at = format!("{here}[{i}]");
                    if schema.is_boolean() {
                        out.push(at);
                    } else {
                        boolean_schema_paths(schema, &at, out);
                    }
                }
            } else if schema_slots.contains(&key.as_str()) {
                // `additionalProperties: false` is a valid keyword value, not a property schema.
                if child.is_boolean() && key != "items" {
                    continue;
                }
                if child.is_boolean() {
                    out.push(here);
                } else {
                    boolean_schema_paths(child, &here, out);
                }
            }
        }
    }

    /// Every `$ref`, `$defs` or `definitions` key under `value` — a schema that
    /// still points at (or carries) a shared definition.
    fn ref_and_def_paths(value: &serde_json::Value, path: &str, out: &mut Vec<String>) {
        match value {
            serde_json::Value::Object(map) => {
                for (key, child) in map {
                    let here = format!("{path}.{key}");
                    if key == "$ref" || key == "$defs" || key == "definitions" {
                        out.push(here);
                    } else {
                        ref_and_def_paths(child, &here, out);
                    }
                }
            }
            serde_json::Value::Array(items) => {
                for (i, item) in items.iter().enumerate() {
                    ref_and_def_paths(item, &format!("{path}[{i}]"), out);
                }
            }
            _ => {}
        }
    }

    /// Writes the served `tools/list` result where `CODESENSE_TOOLS_LIST_OUT` points, for the
    /// Node seam test (`scripts/opencode-mcp-handshake.seam-test.mjs`) that feeds it through
    /// the real bridge to the MCP TypeScript SDK client. No-op when the variable is unset.
    #[test]
    fn export_served_tools_list_for_the_sdk_seam_test() {
        let Some(out) = std::env::var_os("CODESENSE_TOOLS_LIST_OUT") else {
            return;
        };
        let result = serde_json::json!({ "jsonrpc": "2.0", "id": 0, "result": served_tools_list() });
        std::fs::write(out, serde_json::to_vec(&result).unwrap()).unwrap();
    }

    /// MCP TypeScript SDK 1.23+ (OpenCode) rejects the whole `tools/list` result when any
    /// property schema is a bare boolean, which schemars emits for an undocumented
    /// `serde_json::Value` field. Strict clients then show no CodeSense tools at all.
    #[test]
    fn served_tool_schemas_have_no_boolean_property_schemas() {
        let listed = served_tools_list();
        let mut offenders = Vec::new();
        for tool in listed["tools"].as_array().unwrap() {
            let name = tool["name"].as_str().unwrap();
            let schema = &tool["inputSchema"];
            assert!(schema.is_object(), "{name} inputSchema is not an object");
            assert_eq!(schema["type"], "object", "{name} inputSchema type");
            boolean_schema_paths(schema, &format!("{name}.inputSchema"), &mut offenders);
            if let Some(output) = tool.get("outputSchema") {
                assert!(output.is_object(), "{name} outputSchema is not an object");
                boolean_schema_paths(output, &format!("{name}.outputSchema"), &mut offenders);
            }
        }
        assert!(
            offenders.is_empty(),
            "boolean schemas break strict MCP clients; give the field a doc comment or a schema: {offenders:?}"
        );
    }

    /// Moonshot's Kimi Go (behind OpenCode 1.19.4) rejects the whole
    /// `tools/list` result when any input schema keeps a local `$ref` or a
    /// `$defs`/`definitions` map. The served router inlines acyclic local refs
    /// once, so none of these may remain in a served input schema.
    #[test]
    fn served_tool_input_schemas_have_no_local_refs_or_definitions() {
        let listed = served_tools_list();
        let mut offenders = Vec::new();
        for tool in listed["tools"].as_array().unwrap() {
            let name = tool["name"].as_str().unwrap();
            let schema = &tool["inputSchema"];
            ref_and_def_paths(schema, &format!("{name}.inputSchema"), &mut offenders);
        }
        assert!(
            offenders.is_empty(),
            "served input schemas still hold local schema refs/defs; inline them at the served router: {offenders:?}"
        );
    }

    /// Through the served arguments: `sections` keeps only the named parts
    /// (`app_version` and `repos_registered` always, never reported missing), lists each name
    /// that matches nothing once, keeps a viewer read error, and leaves the answer whole when
    /// omitted; the terminal hosts are read only when `terminalLayout` is named. Before
    /// this, `get_viewer_state` took no arguments, always read the hosts and dumped
    /// everything.
    #[tokio::test]
    async fn viewer_state_sections_return_only_the_named_parts() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        let top = serde_json::json!({
            "app_version": "1.0.0",
            "repos_registered": 2,
            "localProfile": {"id": "p"},
            "dependencies": {"git": {"available": true}},
        });
        let viewer = serde_json::json!({"navLens": {"a:b": {"source": "clone"}}, "openTabs": {}});
        let reads = AtomicUsize::new(0);
        let counter = &reads;
        let layouts = move || async move {
            counter.fetch_add(1, Ordering::SeqCst);
            serde_json::json!({"hosts": []})
        };
        let served = |args: serde_json::Value| -> GetViewerStateParams {
            serde_json::from_value(args).expect("the served arguments decode")
        };

        let whole = viewer_state_response(&served(serde_json::json!({})), top.clone(), viewer.clone(), layouts).await;
        assert_eq!(whole["viewer"]["terminalLayout"], serde_json::json!({"hosts": []}));
        assert_eq!(whole["localProfile"], top["localProfile"]);
        assert!(whole.get("missingSections").is_none());
        assert_eq!(reads.load(Ordering::SeqCst), 1);

        let args = serde_json::json!({"sections": ["navLens", "dependencies", "nope", "nope", "app_version"]});
        let cut = viewer_state_response(&served(args), top.clone(), viewer.clone(), layouts).await;
        assert_eq!(
            cut,
            serde_json::json!({
                "app_version": "1.0.0",
                "repos_registered": 2,
                "dependencies": {"git": {"available": true}},
                "viewer": {"navLens": {"a:b": {"source": "clone"}}},
                "missingSections": ["nope"],
            })
        );
        assert_eq!(reads.load(Ordering::SeqCst), 1, "terminalLayout not named: hosts not read");

        let args = serde_json::json!({"sections": ["terminalLayout"]});
        let hosts = viewer_state_response(&served(args), top.clone(), viewer.clone(), layouts).await;
        assert_eq!(hosts["viewer"], serde_json::json!({"terminalLayout": {"hosts": []}}));
        assert_eq!(reads.load(Ordering::SeqCst), 2);

        let unread = serde_json::json!({"error": "viewer state not available"});
        let args = serde_json::json!({"sections": ["openTabs"]});
        let failed = viewer_state_response(&served(args), top, unread, layouts).await;
        assert_eq!(failed["viewer"], serde_json::json!({"error": "viewer state not available"}));
        assert!(failed.get("missingSections").is_none(), "the error says why, not a list");
        assert!(serde_json::from_value::<GetViewerStateParams>(serde_json::json!({"sections": "navLens"})).is_err());
    }

