    /// Claude Code keeps the first 4096 characters of a server's instructions
    /// and of each tool's description, and drops the rest unseen.
    #[test]
    fn served_instructions_and_descriptions_fit_what_a_client_keeps() {
        const KEPT: usize = 4096;
        let instructions = served_instructions();
        assert!(
            instructions.chars().count() <= KEPT,
            "instructions are {} characters",
            instructions.chars().count()
        );
        let long: Vec<_> = CodesenseHandler::served_tool_router()
            .list_all()
            .into_iter()
            .filter_map(|tool| {
                let length = tool.description.as_deref().unwrap_or("").chars().count();
                (length > KEPT).then(|| format!("{} ({length})", tool.name))
            })
            .collect();
        assert!(long.is_empty(), "descriptions over {KEPT}: {long:?}");
    }

    /// The Anthropic API refuses a tool whose input schema has a combinator at
    /// its root, and once such a tool loads every later request fails. No
    /// served tool may publish one.
    #[test]
    fn served_tool_input_schemas_have_no_top_level_combinators() {
        let listed = served_tools_list();
        let tools = listed["tools"].as_array().unwrap();
        assert!(!tools.is_empty());
        let mut offenders = Vec::new();
        for tool in tools {
            let name = tool["name"].as_str().unwrap();
            let schema = tool["inputSchema"].as_object().unwrap();
            if schema.get("type") != Some(&json!("object")) {
                offenders.push(format!("{name}: root type is not object"));
            }
            for combinator in ["anyOf", "oneOf", "allOf"] {
                if schema.contains_key(combinator) {
                    offenders.push(format!("{name}: top-level {combinator}"));
                }
            }
        }
        assert!(offenders.is_empty(), "{offenders:#?}");
    }

    #[test]
    fn served_tool_input_schemas_have_object_roots_and_flat_multi_form_params() {
        #[allow(unused_mut)]
        let mut generated = CodesenseHandler::tool_router();
        // Feature-enabled builds serve the publish verbs from their own router too.
        #[cfg(feature = "dashboard-publish")]
        generated.merge(CodesenseHandler::publish_tool_router());
        let listed = served_tools_list();
        for tool in listed["tools"].as_array().unwrap() {
            let name = tool["name"].as_str().unwrap();
            let mut expected = generated.get(name).unwrap().input_schema.as_ref().clone();
            expected.insert("type".into(), json!("object"));
            crate::mcp::schema_inline::inline_refs(&mut expected).unwrap();
            assert_eq!(tool["inputSchema"]["type"], "object", "{name}");
            assert_eq!(tool["inputSchema"], json!(expected), "{name}");
        }
        // The multi-form tools publish every form's fields in one closed object.
        let scope_less = ["codeRepoPath", "sessionId"];
        for (name, fields) in [
            (
                "hydrate_worktree",
                vec![
                    "target",
                    "context",
                    "paths",
                    "sets",
                    "prune",
                    "overwriteModified",
                    "operationId",
                    "kind",
                    "requestId",
                    "items",
                ],
            ),
            (
                "reverse_sync_worktree",
                vec![
                    "target",
                    "context",
                    "paths",
                    "sets",
                    "to",
                    "includeDeletes",
                    "operationId",
                    "kind",
                    "requestId",
                    "items",
                ],
            ),
            (
                "preview_reverse_sync_worktree",
                vec![
                    "target",
                    "context",
                    "paths",
                    "sets",
                    "to",
                    "includeDeletes",
                    "kind",
                    "items",
                ],
            ),
            (
                "context_operation_status",
                vec!["operationId", "target", "requestId"],
            ),
            (
                "open_remote_tab",
                vec![
                    "operation",
                    "requestId",
                    "machineId",
                    "teamKey",
                    "workspaceId",
                    "cwd",
                    "kind",
                    "launch",
                    "permissionMode",
                    "agentKey",
                    "preparedWorkspaceHandle",
                    "headed",
                    "name",
                    "launchedBy",
                    "handle",
                ],
            ),
        ] {
            let tool = listed["tools"]
                .as_array()
                .unwrap()
                .iter()
                .find(|tool| tool["name"] == name)
                .unwrap_or_else(|| panic!("{name} not served"));
            let schema = &tool["inputSchema"];
            assert_eq!(schema["additionalProperties"], json!(false), "{name}");
            let mut expected: Vec<&str> = fields;
            if name != "context_operation_status" && name != "open_remote_tab" {
                expected.extend(scope_less);
            }
            expected.sort_unstable();
            let mut published: Vec<&str> = schema["properties"]
                .as_object()
                .unwrap_or_else(|| panic!("{name}: no properties"))
                .keys()
                .map(String::as_str)
                .collect();
            published.sort_unstable();
            assert_eq!(published, expected, "{name}");
            // An optional field publishes no `default: null` its type refuses.
            for (field, property) in schema["properties"].as_object().unwrap() {
                assert!(
                    property.get("default") != Some(&serde_json::Value::Null),
                    "{name}.{field} publishes default: null"
                );
            }
        }
        // The launch field keeps its finite enum.
        let open = listed["tools"]
            .as_array()
            .unwrap()
            .iter()
            .find(|tool| tool["name"] == "open_remote_tab")
            .unwrap();
        assert_eq!(
            open["inputSchema"]["properties"]["launch"]["enum"],
            json!(["shell", "claude", "codex"])
        );
        // Only the fields both forms need are required; the rest are per form.
        let mut required: Vec<&str> = open["inputSchema"]["required"]
            .as_array()
            .unwrap()
            .iter()
            .map(|field| field.as_str().unwrap())
            .collect();
        required.sort_unstable();
        assert_eq!(required, ["machineId", "operation", "teamKey"]);
        // The runtime decoder still rejects mixing the create and attach forms.
        let mixed = json!({
            "operation": "attach", "machineId": "host", "teamKey": "org:team",
            "handle": "opaque", "launch": "codex"
        });
        assert!(serde_json::from_value::<OpenRemoteTabParams>(mixed.clone()).is_err());
        assert_eq!(
            serde_json::from_value::<OpenRemoteTabToolParams>(mixed)
                .unwrap()
                .into_params()
                .unwrap_err(),
            "invalid: attach does not take launch"
        );
    }

    /// `open_workspace` takes the camelCase keys its description, the docs
    /// and the dashboard bridge use (`storyId`, `launchedBy`, `initialPrompt`,
    /// `machineId`), and still takes the snake_case keys existing callers send.
    #[test]
    fn open_workspace_params_take_camel_and_snake_case_keys() {
        let camel: OpenWorkspaceParams = serde_json::from_value(json!({
            "storyId": "SW-1", "target": "story", "launchedBy": "tab-1",
            "initialPrompt": "/review", "machineId": "local"
        }))
        .unwrap();
        assert_eq!(camel.story_id.as_deref(), Some("SW-1"));
        assert_eq!(camel.launched_by.as_deref(), Some("tab-1"));
        assert_eq!(camel.initial_prompt.as_deref(), Some("/review"));
        assert_eq!(camel.machine_id.as_deref(), Some("local"));
        let snake: OpenWorkspaceParams = serde_json::from_value(json!({
            "story_id": "SW-2", "launched_by": "tab-2",
            "initial_prompt": "/fix", "machine_id": "mac-2"
        }))
        .unwrap();
        assert_eq!(snake.story_id.as_deref(), Some("SW-2"));
        assert_eq!(snake.launched_by.as_deref(), Some("tab-2"));
        assert_eq!(snake.initial_prompt.as_deref(), Some("/fix"));
        assert_eq!(snake.machine_id.as_deref(), Some("mac-2"));
        // Unknown keys are still refused.
        assert!(serde_json::from_value::<OpenWorkspaceParams>(json!({"storyID": "SW-3"})).is_err());
    }

