    /// Canonical list of MCP tool names this handler exposes. Used by
    /// `mcp_tools_registered` (self-parity: scans `handler.rs` source) so
    /// adding or renaming a tool fails the test until the list is updated.
    #[test]
    fn retired_repository_mutations_are_absent_from_discovery_and_dispatch() {
        let router = CodesenseHandler::served_tool_router();
        for name in [
            "publish_remote_workspace",
            "gs_snapshot",
            "gs_integrate",
            "gs_submit_resolution",
            "gs_publish",
            "gs_absorb_pull",
            "gs_status",
            "get_pull_set",
            "gs_report_status",
        ] {
            assert!(
                router.get(name).is_none(),
                "retired tool remains callable: {name}"
            );
        }
        assert!(router.get("get_publish_set").is_some());
    }

    #[test]
    fn routine_cancel_is_discoverable_with_a_single_run_schema() {
        let router = CodesenseHandler::served_tool_router();
        let tool = router
            .get("routine_cancel")
            .expect("routine_cancel is served");
        let schema = serde_json::Value::Object((*tool.input_schema).clone());
        assert_eq!(schema["required"], serde_json::json!(["runId"]));
        assert_eq!(schema["properties"]["runId"]["type"], "string");
        assert!(schema["properties"].get("sessionId").is_some());
        assert!(schema["properties"].get("key").is_none());
        assert!(schema["properties"].get("id").is_none());
        let description = tool.description.as_deref().unwrap();
        assert!(description.contains("verified connection"));
        assert!(description.contains("routine_runs"));
        assert!(description.contains("validation"));
    }

