    // The agent never handles a secret — there is NO MCP tool that sets a connector
    // credential (a token in a tool arg would leak into the transcript/logs/model context). This
    // pins the carve against a future re-add: the register tool is exposed, but no credential setter.
    #[test]
    fn no_set_credential_tool_is_exposed() {
        assert!(
            !EXPECTED_MCP_TOOLS.contains(&"register_connector"),
            "retired register_connector must be absent"
        );
        assert!(
            !EXPECTED_MCP_TOOLS
                .iter()
                .any(|t| t.contains("credential") || t.contains("token") || t.contains("secret")),
            "AC-2: no MCP tool may set a connector secret — none was expected, but one appears"
        );
    }

    /// Directory ownership is gone (X4), so the per-surface
    /// designation writer is neither served nor listed. Spelled in two parts so
    /// a search for the retired name finds only its absence.
    #[test]
    fn xs5_the_surface_scope_writer_is_not_served() {
        let retired = concat!("set_surface", "_scope");
        let router = CodesenseHandler::served_tool_router();
        assert!(router.get(retired).is_none(), "{retired} is still served");
        assert!(
            !router
                .list_all()
                .iter()
                .any(|tool| tool.name.contains("surface_scope")),
            "no served tool writes a surface scope"
        );
        assert!(
            !EXPECTED_MCP_TOOLS.contains(&retired),
            "{retired} is still listed"
        );
    }

    /// The agent tools are served and listed, the retired profile writer is
    /// gone from both, and the descriptions teach what an agent needs to get
    /// right.
    #[test]
    fn the_agent_tools_are_served_and_the_profile_writer_is_gone() {
        let agent_tools = [
            "agent_list",
            "agent_get",
            "agent_preview",
            "agent_create",
            "agent_update",
            "agent_delete",
            "agent_restore",
            "agent_unarchive",
        ];
        let router = CodesenseHandler::served_tool_router();
        let mut served: Vec<String> = router
            .list_all()
            .into_iter()
            .map(|tool| tool.name.to_string())
            .filter(|name| name.starts_with("agent_"))
            .collect();
        served.sort();
        let mut expected: Vec<String> = agent_tools.iter().map(|n| n.to_string()).collect();
        expected.sort();
        assert_eq!(served, expected);
        for name in agent_tools {
            assert!(EXPECTED_MCP_TOOLS.contains(&name), "{name} is listed");
            let description = router
                .get(name)
                .and_then(|tool| tool.description.clone())
                .unwrap_or_default();
            assert!(description.contains("Returns"), "{name} states its reply");
            assert!(
                !description.to_lowercase().contains("notif"),
                "{name} promises no notice"
            );
        }
        // Spelled in two parts so a search for the retired name finds only
        // its absence.
        let retired = concat!("upsert", "_profile");
        assert!(router.get(retired).is_none());
        assert!(!EXPECTED_MCP_TOOLS.contains(&retired));

        let create = router
            .get("agent_create")
            .map(served_text)
            .unwrap_or_default();
        for lesson in [
            "`agent_create {name, runtime}` is a complete agent",
            "`runtime` (`claude`, `codex` or `opencode`: the built-in CLI;",
            "plain content-relative paths",
            "never `skill:`/`command:` keys",
            "native config, passed through verbatim and enforced by the CLI, never by CodeSense",
            "each user runs it with their own Claude, Codex or OpenCode CLI login",
            "shared with the team by the user's own git push",
            "`.claude/commands/name.md`",
            "no bypass flag is ever added for you",
            "never goes in agent.yaml",
        ] {
            assert!(create.contains(lesson), "agent_create teaches {lesson:?}");
        }
        let create_tool = router.get("agent_create").expect("agent_create");
        let properties = create_tool
            .input_schema
            .get("properties")
            .and_then(|p| p.as_object())
            .expect("agent_create has properties");
        for field in [
            "name",
            "runtime",
            "startup",
            "mcpServers",
            "permissions",
            "dryRun",
            "sessionId",
            "scope",
        ] {
            assert!(properties.contains_key(field), "agent_create takes {field}");
        }
        let update = router
            .get("agent_update")
            .and_then(|tool| tool.description.clone())
            .unwrap_or_default();
        assert!(update.contains("`baseRevision`") && update.contains("conflict"));
        let list = router
            .get("agent_list")
            .and_then(|tool| tool.description.clone())
            .unwrap_or_default();
        assert!(list.contains("view filter, not permission"));
        // The preview takes the create fields flat, as the skill teaches.
        let preview = router.get("agent_preview").expect("agent_preview");
        let preview_props = preview
            .input_schema
            .get("properties")
            .and_then(|p| p.as_object())
            .expect("agent_preview has properties");
        for field in ["name", "runtime", "startup", "permissions", "scope"] {
            assert!(
                preview_props.contains_key(field),
                "agent_preview takes {field}"
            );
        }
        assert!(!preview_props.contains_key("draft"));
    }

    /// An agent reads and sets the rates usage is priced with: `model_rates` takes nothing, and
    /// `set_model_rate` asks for the page's `setModelRate` fields, with the model, the day and the
    /// input and output prices required, and says a rate is the user's to give.
    #[test]
    fn the_rate_tools_are_served() {
        let router = CodesenseHandler::served_tool_router();
        let rates = router.get("model_rates").expect("model_rates");
        let no_inputs = rates
            .input_schema
            .get("properties")
            .and_then(|p| p.as_object())
            .is_none_or(|p| p.is_empty());
        assert!(no_inputs, "model_rates takes no inputs");
        let set = router.get("set_model_rate").expect("set_model_rate");
        let properties = set
            .input_schema
            .get("properties")
            .and_then(|p| p.as_object())
            .expect("set_model_rate has properties");
        let mut fields: Vec<&str> = properties.keys().map(String::as_str).collect();
        fields.sort_unstable();
        assert_eq!(
            fields,
            [
                "cacheReadPerMtok",
                "effectiveFrom",
                "inputPerMtok",
                "long",
                "modelPrefix",
                "outputPerMtok"
            ]
        );
        let mut required: Vec<&str> = set
            .input_schema
            .get("required")
            .and_then(|r| r.as_array())
            .expect("set_model_rate has required inputs")
            .iter()
            .filter_map(|v| v.as_str())
            .collect();
        required.sort_unstable();
        assert_eq!(
            required,
            [
                "effectiveFrom",
                "inputPerMtok",
                "modelPrefix",
                "outputPerMtok"
            ]
        );
        let description = set.description.clone().unwrap_or_default();
        assert!(description.contains("only with prices the user gave or confirmed"));
    }

    /// A rate or usage input the store refuses reaches the agent as an invalid request it can fix;
    /// any other store error is internal. Both name the tool.
    #[test]
    fn a_refused_usage_input_is_an_invalid_request_and_a_store_failure_is_internal() {
        let refused = usage_err(
            "set_model_rate",
            "invalid: effectiveFrom must be YYYY-MM-DD, got \"2026-13-01\"".to_string(),
        );
        assert_eq!(refused.code, rmcp::model::ErrorCode::INVALID_PARAMS);
        assert!(refused
            .message
            .starts_with("set_model_rate: invalid: effectiveFrom"));
        let failed = usage_err("set_model_rate", "database is locked".to_string());
        assert_eq!(failed.code, rmcp::model::ErrorCode::INTERNAL_ERROR);
        assert_eq!(failed.message, "set_model_rate: database is locked");
    }

    /// The routine tools are served with descriptions that
    /// state what they return, and `routine_create` asks for its three required
    /// inputs by the names its description uses.
    #[test]
    fn the_routine_tools_are_served() {
        let tools = [
            "routine_create",
            "routine_list",
            "routine_get",
            "routine_update",
            "routine_set_enabled",
            "routine_run_now",
            "routine_runs",
            "routine_run",
            "routine_cancel",
            "routine_delete",
            "routine_context",
            "routine_publish_result",
            "routine_done",
            "routine_result",
            "routine_arm_on",
            "routine_handover_release",
            "routine_refresh_on_machine",
        ];
        let router = CodesenseHandler::served_tool_router();
        let mut served: Vec<String> = router
            .list_all()
            .into_iter()
            .map(|tool| tool.name.to_string())
            .filter(|name| name.starts_with("routine_"))
            .collect();
        served.sort();
        let mut expected: Vec<String> = tools.iter().map(|n| n.to_string()).collect();
        expected.sort();
        assert_eq!(served, expected);
        let mut listed: Vec<&str> = EXPECTED_MCP_TOOLS
            .iter()
            .copied()
            .filter(|name| name.starts_with("routine_"))
            .collect();
        listed.sort();
        assert_eq!(listed, expected);
        for name in tools {
            let description = router
                .get(name)
                .and_then(|tool| tool.description.clone())
                .unwrap_or_default();
            assert!(
                description.contains("Returns") && description.contains("status"),
                "{name} must state its returned envelope"
            );
        }
        let create = router.get("routine_create").expect("routine_create");
        let schema = serde_json::to_value(&create.input_schema).unwrap();
        let required = schema["required"].as_array().cloned().unwrap_or_default();
        // `task` is optional: a command routine runs `command` instead.
        assert_eq!(required, vec![json!("name")], "only name is required");
        // An agent CodeSense did not launch has no session id, and may still
        // use the service through a native caller. MCP binds the optional field
        // to its verified connection before dispatch.
        for name in [
            "routine_create",
            "routine_update",
            "routine_set_enabled",
            "routine_run_now",
            "routine_cancel",
            "routine_delete",
        ] {
            let tool = router.get(name).expect(name);
            let schema = serde_json::to_value(&tool.input_schema).unwrap();
            assert!(
                schema["properties"].get("sessionId").is_some(),
                "{name} takes a sessionId"
            );
            let required = schema["required"].as_array().cloned().unwrap_or_default();
            assert!(
                !required.contains(&json!("sessionId")),
                "{name} must not require a sessionId"
            );
        }
        for field in ["where", "dryRun", "enabled", "maxRuntime"] {
            assert!(
                schema["properties"].get(field).is_some(),
                "routine_create takes {field}"
            );
        }
        let context = router.get("routine_context").expect("routine_context");
        let schema = serde_json::to_value(&context.input_schema).unwrap();
        assert_eq!(schema["required"], json!(["sessionId"]));
    }

    #[test]
    fn routine_events_are_documented_in_served_schemas_and_descriptions() {
        let router = CodesenseHandler::served_tool_router();
        for name in ["routine_create", "routine_update"] {
            let tool = router.get(name).unwrap();
            let schema = serde_json::to_value(&tool.input_schema).unwrap();
            assert!(schema["properties"].get("events").is_some());
            let description = tool.description.clone().unwrap();
            assert!(description.chars().count() <= 4096, "{name}");
            assert_eq!(description.matches("Docs:").count(), 1, "{name}");
            assert!(description.contains("arc-g-routines/trigger-cookbook.html"));
            for example in [
                r#"{kind:"inbox_idle"}"#,
                r#"{kind:"agent_done",from_agent:"reviewer"}"#,
                r#"{kind:"role_pending"}"#,
                r#"{kind:"role_pending",role:"reviewer"}"#,
            ] {
                assert!(description.contains(example), "{name} missing {example}");
            }
            if name == "routine_update" {
                assert!(schema["properties"].get("dryRun").is_none());
            }
        }
    }

    /// The timer tools are served; each names the caller's own
    /// `sessionId` as required (bound to the transport, never trusted alone),
    /// `schedule_wakeup` asks for `prompt` and offers `in`/`at`/`every`/
    /// `until`/`count`/`name`, and the removed `whenIdleOnly` is not offered.
    #[test]
    fn the_timer_tools_are_served_for_the_callers_own_session() {
        let router = CodesenseHandler::served_tool_router();
        for name in ["schedule_wakeup", "list_wakeups", "cancel_wakeup"] {
            assert!(EXPECTED_MCP_TOOLS.contains(&name), "{name} is listed");
            let tool = router.get(name).expect(name);
            let schema = serde_json::to_value(&tool.input_schema).unwrap();
            let required = schema["required"].as_array().cloned().unwrap_or_default();
            assert!(
                required.contains(&json!("sessionId")),
                "{name}: {required:?}"
            );
            let description = tool.description.clone().unwrap_or_default();
            assert!(description.contains("Returns"), "{name}");
            assert!(
                description.contains("another session's id is refused"),
                "{name}"
            );
        }
        let schedule = router.get("schedule_wakeup").unwrap();
        let schema = serde_json::to_value(&schedule.input_schema).unwrap();
        let mut required: Vec<String> = schema["required"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect();
        required.sort();
        assert_eq!(required, ["prompt", "sessionId"]);
        for field in ["in", "at", "every", "until", "count", "name"] {
            assert!(schema["properties"].get(field).is_some(), "takes {field}");
        }
        assert!(schema["properties"].get("whenIdleOnly").is_none());
        let description = schedule.description.clone().unwrap_or_default();
        assert!(
            description.starts_with(
                "Schedule wakeup — temporary routine / reminder for THIS session only — use it when asked to 'add a routine for your session', 'remind yourself', or 'check X every N minutes'. Unlike routine_create (a saved routine on an Agent that wakes its running session or starts a new one, and persists), the prompt is typed into this same conversation so you keep your context, and it ends when this session ends."
            ),
            "schedule_wakeup opens by telling it apart from routine_create"
        );
        for clause in [
            "not for headless runs",
            "keep firing",
            "10 active timers",
            "up to 24 h",
            "366 days",
            "date +%z",
        ] {
            assert!(description.contains(clause), "states {clause:?}");
        }
        // The reverse pointer: a saved routine's tool sends session-only asks here.
        let create = router
            .get("routine_create")
            .and_then(|tool| tool.description.clone())
            .unwrap_or_default();
        assert!(
            create.contains("For something only for your current session, use schedule_wakeup.")
        );
        let cancel = router.get("cancel_wakeup").unwrap();
        let schema = serde_json::to_value(&cancel.input_schema).unwrap();
        assert!(schema["required"]
            .as_array()
            .unwrap()
            .contains(&json!("timerId")));
    }

    /// Whoever writes a routine's task learns the run contract from the tools
    /// that take it, since nothing is added to the task at run time.
    #[test]
    fn the_routine_write_tools_state_the_run_contract() {
        let router = CodesenseHandler::served_tool_router();
        for name in ["routine_create", "routine_update"] {
            let description = router
                .get(name)
                .and_then(|tool| tool.description.clone())
                .unwrap_or_default();
            for clause in [
                "whole contract",
                "when the agent process exits, when it calls `signal_done`, or at `maxRuntime`",
                "status `needs-attention`",
                "otherwise the run simply ends",
                "until the user closes the tab or `maxRuntime`",
                "`routine_context`",
                "Routines never deliver results",
            ] {
                assert!(description.contains(clause), "{name} states {clause:?}");
            }
        }
        let create = router
            .get("routine_create")
            .and_then(|tool| tool.description.clone())
            .unwrap_or_default();
        assert!(create.contains("the agent's whole prompt"));
        assert!(create.contains("CodeSense adds nothing to it"));
    }

    /// A routine write made from a session takes that session's launch
    /// profile, whoever's personal space it was launched from; an unknown
    /// session carries nothing.
    #[test]
    fn a_routine_caller_session_reads_its_launch_record() {
        use crate::commands::dashboard_launch::{DashboardLaunchState, SessionOwner};
        let state = DashboardLaunchState::default();
        state.register("h-1", "sess-1", None);
        state.set_profile_id_if_absent("h-1", "reviewer".into());
        state.set_owner_if_absent(
            "h-1",
            SessionOwner {
                principal: Some("1".into()),
                org: "acme".into(),
                team: None,
            },
        );
        state.set_agent_revision_if_absent("h-1", "acme/api/backend/triage@3".into());
        let session = launched_caller(&state, "sess-1");
        assert_eq!(session.profile_id.as_deref(), Some("reviewer"));
        assert_eq!(
            session.agent,
            Some(crate::agents::AgentKey::new(
                "acme/api", "backend", "triage"
            ))
        );

        let session = launched_caller(&state, "unknown");
        assert!(
            session.profile_id.is_none()
                && session.account_runtime.is_none()
                && session.agent.is_none()
        );
    }

    #[test]
    fn routine_publication_requires_positive_launch_principal_even_after_restore() {
        use crate::commands::dashboard_launch::{DashboardLaunchState, SessionOwner};
        let guest = Principal::from(crate::domain::LOCAL_GUEST_USER_ID);
        let state = DashboardLaunchState::default();
        state.register("visible-restored", "session", None);
        let matches = |state: &DashboardLaunchState, principal: &Principal| {
            let owner = state
                .owner_for_session("session")
                .and_then(|owner| owner.principal);
            routine_publication_owner_matches(owner.as_deref(), principal)
        };
        assert!(
            !matches(&state, &guest),
            "restored visible session without provenance must fail closed"
        );
        assert!(!routine_publication_owner_matches(None, &guest));
        state.set_owner_if_absent(
            "visible-restored",
            SessionOwner {
                principal: Some(guest.to_string()),
                org: "local/context".into(),
                team: Some("team".into()),
            },
        );
        assert!(
            matches(&state, &guest),
            "recorded local guest launch is authorized"
        );
        assert!(
            !matches(&state, &Principal::from(1u64)),
            "foreign launch principal is rejected"
        );
        assert!(!routine_publication_owner_matches(Some(""), &guest));
    }

    /// The `get_sync_status` wire contract — per-surface
    /// shape, org-scoping, and the kebab-case `status` serialization an
    /// external agent depends on.
    #[test]
    fn sync_status_payload_shape_and_org_scope() {
        use crate::domain::SourceRepoSlug;
        use crate::install::worktree_index::{SyncStatus, WorktreeStoryRecord};

        let mut in_org = WorktreeStoryRecord::new(
            "/abs/wt-a",
            "acme/api",
            SourceRepoSlug::new("acme", "api").unwrap(),
            "SW-TS-3",
            "/srv/users/1/orgs/acme/api/codesense-context/default/content/SW-TS-3.md",
        );
        // A stale pre-upgrade stamp: nothing writes these any more.
        in_org.status = SyncStatus::Failed;
        in_org.pending_wave = Some(42);
        in_org.failure_reason = Some("materialize blew up".to_string());
        in_org.retry_attempts = 2;

        let other_org = WorktreeStoryRecord::new(
            "/abs/wt-b",
            "other/repo",
            SourceRepoSlug::new("other", "repo").unwrap(),
            "X-1",
            "/srv/users/1/orgs/other/repo/codesense-context/default/content/X-1.md",
        );

        let recent = vec![crate::mcp::context_operations::explicit::OperationRecord {
            operation_id: "op".into(),
            kind: "hydrate".into(),
            state: "ready".into(),
            target: serde_json::json!({"kind":"local"}),
            authority: None,
            started_at_ms: 1,
            finished_at_ms: Some(2),
            result: None,
        }];
        let payload = sync_status_payload(vec![in_org.clone(), other_org], "acme/api", recent);
        // Redefined as {setupState, recentOperations}.
        assert_eq!(payload["recentOperations"][0]["state"], "ready");
        assert_eq!(payload["recentOperations"][0]["operationId"], "op");
        let surfaces = payload["setupState"].as_array().expect("setupState array");
        assert_eq!(surfaces.len(), 1, "other-org record must be filtered out");
        let s = &surfaces[0];
        assert_eq!(s["codeRepoPath"], "/abs/wt-a");
        assert_eq!(s["storyId"], "SW-TS-3");
        assert_eq!(s["intendedTeam"], "default");
        assert_eq!(s["setupComplete"], in_org.setup_complete);
        // Stale wave stamps and auto-retry bookkeeping are not reported.
        for gone in [
            "status",
            "pendingWave",
            "failureReason",
            "retryAttempts",
            "maxAttempts",
            "nextRetryAt",
            "outOfDate",
        ] {
            assert!(s.get(gone).is_none(), "`{gone}` must not be reported");
        }
    }

    /// The agent-facing descriptions promise no fan-out or wave.
    #[test]
    fn agent_facing_descriptions_promise_no_automatic_sync() {
        let src = include_str!("handler.rs");
        for (tool, banned) in [
            ("fn get_sync_status", "wave engine stamps"),
            ("fn delete_content_file", "every projected dest"),
            ("fn move_content_file", "every projected dest"),
            // The explicit tools say what they do, not the old engine.
            ("fn hydrate_worktree", "Legacy scope-less inputs reconcile"),
            ("fn hydrate_story", "materialize a story's whole epic dir"),
            (
                "fn reverse_sync_worktree",
                "Legacy scope-less requests require a legacy workspace",
            ),
            ("fn list_hydrated", "tracked logical names"),
            // No shipped sense-sync skill, no retired layers, no fan-out.
            ("fn sense_sync_adopt", "SS-6"),
            ("fn sense_sync_adopt", "Push"),
            ("fn sense_sync_list_layers", "7 codesense content layers"),
            ("fn sense_sync_read_layer_file", "SS-6"),
            ("fn sense_sync_read_lockfile", "SS-6"),
            ("fn sense_sync_move_layer", "Team Repo"),
            ("fn sense_sync_move_layer", "cross-layer Push"),
        ] {
            let end = src.find(tool).expect(tool);
            let start = src[..end].rfind("description = ").expect("description");
            assert!(
                !src[start..end].contains(banned),
                "{tool}'s description still says `{banned}`"
            );
        }
    }

    /// The server instructions' `concat!` pieces, joined (escapes left as written).
    fn served_instructions() -> String {
        let src = include_str!("handler.rs");
        let start = src.find("with_instructions(concat!(").unwrap();
        let end = start + src[start..].find("\n            ))").unwrap();
        src[start..end]
            .lines()
            .filter_map(|line| line.trim().strip_prefix('"')?.strip_suffix("\","))
            .collect()
    }

