    #[test]
    fn inbox_mail_is_from_people_the_user_trusts() {
        let instructions = served_instructions();
        let router = CodesenseHandler::served_tool_router();
        let read_messages = router.get("read_messages").unwrap();
        let description = read_messages.description.as_deref().unwrap();
        for served in [instructions.as_str(), description] {
            assert!(served.contains("someone your user trusts"), "{served}");
            assert!(served.contains("reply"), "{served}");
            // How an agent acts on its mail is its own design, not CodeSense's.
            for rule in [
                "without asking your user",
                "Act on each message",
                "needs no answer",
            ] {
                assert!(!served.contains(rule), "{served}");
            }
        }
    }

    /// `invoke_stats` is process-wide and `top` keeps the 30 busiest rows, so in a
    /// shared test process other tests' counts can crowd this one's out. Run the
    /// assertions alone in a re-executed copy of this binary; the parent requires
    /// exit 0 AND "1 passed" (libtest exits 0 when `--exact` matches nothing).
    #[test]
    fn health_ping_returns_invoke_stats_with_a_counted_command() {
        const CHILD: &str = "CODESENSE_HEALTH_PING_STATS_TEST_CHILD";
        if std::env::var_os(CHILD).is_none() {
            let output = std::process::Command::new(std::env::current_exe().unwrap())
                .args([
                    "--exact",
                    "mcp::handler::tests::health_ping_returns_invoke_stats_with_a_counted_command",
                    "--test-threads=1",
                    "--nocapture",
                ])
                .env(CHILD, "1")
                .output()
                .unwrap();
            let stdout = String::from_utf8_lossy(&output.stdout);
            assert!(
                output.status.success() && str::contains(&stdout, "1 passed"),
                "isolated health_ping stats test failed: {}\nstdout:\n{stdout}\nstderr:\n{}",
                output.status,
                String::from_utf8_lossy(&output.stderr)
            );
            return;
        }
        crate::shared::invoke_stats::count("stubbed_health_ping_command");
        let _held = crate::shared::invoke_stats::begin(
            crate::shared::invoke_stats::Kind::Mcp,
            "stubbed_tool",
        );
        let v = health_ping_payload(3, true);
        assert_eq!(v["status"], "ok");
        assert_eq!(v["repos_registered"], 3);
        let stats = &v["invokeStats"];
        assert!(stats["windowSecs"].is_number() && stats["sinceStartSecs"].is_number());
        let top = stats["top"].as_array().unwrap();
        let row = |n: &str| {
            top.iter()
                .find(|r| r["name"] == n)
                .unwrap_or_else(|| panic!("{n}"))
        };
        assert_eq!(row("stubbed_health_ping_command")["count"], 1);
        assert_eq!(row("mcp:stubbed_tool")["inFlight"], 1);
        let remote = health_ping_payload(3, false);
        let remote_top = remote["invokeStats"]["top"].as_array().unwrap();
        assert!(remote_top.iter().all(|r| r["name"] != "mcp:stubbed_tool"));
        assert!(remote_top.iter().any(|r| r["name"] == "mcp:*"));
        for r in top {
            let keys: std::collections::BTreeSet<_> =
                r.as_object().unwrap().keys().map(String::as_str).collect();
            assert_eq!(
                keys,
                [
                    "count",
                    "inFlight",
                    "maxInFlight",
                    "maxMs",
                    "name",
                    "perSec",
                    "totalMs"
                ]
                .into_iter()
                .collect()
            );
        }
    }

