    #[test]
    fn decode_layer_file_content_returns_utf8_for_text() {
        let v = decode_layer_file_content(b"hello world".to_vec());
        assert_eq!(v["contentUtf8"], json!("hello world"));
        assert!(v.get("error").is_none());
    }

    #[test]
    fn decode_layer_file_content_returns_binary_marker_for_non_utf8() {
        // Invalid UTF-8 byte sequence: lone continuation byte.
        let v = decode_layer_file_content(vec![0xC3, 0x28]);
        assert_eq!(v["error"], json!("binary"));
        // Review iter-1 (M-4): binary response now carries byteLength so
        // the skill can confirm the file is real, just unrenderable.
        assert_eq!(v["byteLength"], json!(2));
        assert!(v.get("contentUtf8").is_none());
    }

