    #[test]
    fn close_workspace_params_accept_camel_and_snake_case() {
        // Input hygiene: the serde aliases make both camelCase
        // (TypeScript style, the FE bridge) and snake_case (Rust tests,
        // scripts) land in the same struct — a regression here is subtle.
        let camel: CloseWorkspaceParams = serde_json::from_value(json!({
            "storyId": "SW-WA-F7",
            "discardUnsaved": true,
            "machineId": "local",
        }))
        .unwrap();
        assert_eq!(camel.story_id.as_deref(), Some("SW-WA-F7"));
        assert_eq!(camel.discard_unsaved, Some(true));
        assert_eq!(camel.machine_id.as_deref(), Some("local"));
        let snake: CloseWorkspaceParams = serde_json::from_value(json!({
            "story_id": "SW-WA-F7",
            "discard_unsaved": false,
        }))
        .unwrap();
        assert_eq!(snake.story_id.as_deref(), Some("SW-WA-F7"));
        assert_eq!(snake.discard_unsaved, Some(false));
        // deny_unknown_fields keeps the surface tight.
        assert!(
            serde_json::from_value::<CloseWorkspaceParams>(json!({"storyID": "SW-WA-F7"})).is_err()
        );
    }

    #[test]
    fn is_self_closing_tab_matches_only_the_caller_in_the_tab_list() {
        // The shared selfClose predicate used by both
        // `close_terminal_tab` and `close_workspace`. A caller is self-closing
        // only when it names a session the verb would tear down. `None`
        // (an inbound call from outside any tab, like the app's own UI path)
        // is never self-closing. An empty session list is never self-closing.
        assert!(super::is_self_closing_tab(
            Some("sess-7"),
            std::iter::once("sess-7")
        ));
        assert!(super::is_self_closing_tab(
            Some("sess-7"),
            ["sess-1", "sess-7", "sess-3"].iter().copied()
        ));
        assert!(!super::is_self_closing_tab(
            Some("sess-7"),
            ["sess-1", "sess-2"].iter().copied()
        ));
        assert!(!super::is_self_closing_tab(
            Some("sess-7"),
            std::iter::empty::<&str>()
        ));
        assert!(!super::is_self_closing_tab(
            None,
            ["sess-1", "sess-7"].iter().copied()
        ));
    }

    /// The self-close refusal of `close_terminal_tab` is decided
    /// before it touches its tab. (`close_workspace` has its own outcome tests
    /// over `plan_close`, which refuses a self-close before any teardown.)
    #[test]
    fn close_terminal_tab_refuses_self_close_before_any_teardown() {
        let source = include_str!("handler.rs");
        let verb = "close_terminal_tab";
        let at = source
            .find(&format!("    async fn {verb}(\n"))
            .unwrap_or_else(|| panic!("{verb} is a tool"));
        let next_fn = source[at + 1..]
            .find("\n    async fn ")
            .map(|i| at + 1 + i)
            .unwrap_or(source.len());
        let body = &source[at..next_fn];
        let self_close = body
            .find("is_self_closing_tab(")
            .unwrap_or_else(|| panic!("{verb} must call is_self_closing_tab"));
        let teardown = body
            .find("terminal_close_tab(")
            .unwrap_or_else(|| panic!("{verb} must call terminal_close_tab"));
        assert!(
            self_close < teardown,
            "{verb} must refuse selfClose before any terminal_close_tab call"
        );
        assert!(
            body.contains("\"reason\": \"selfClose\""),
            "{verb} must return reason:selfClose"
        );
    }

    #[test]
    fn close_terminal_tab_params_require_handle_and_reject_extras() {
        // A tab close never touches the worktree, so there is no
        // `discardUnsaved` here. `deny_unknown_fields` keeps the signature
        // tight — a stray `discardUnsaved` from a caller who confused the two
        // verbs reads as a programmer error, not a silent no-op.
        let p: CloseTerminalTabParams =
            serde_json::from_value(json!({"handle": "term-tab-1"})).unwrap();
        assert_eq!(p.handle, "term-tab-1");
        // No handle → refused.
        assert!(serde_json::from_value::<CloseTerminalTabParams>(json!({})).is_err());
        // Any extra field → refused (including the retired `discardUnsaved`).
        assert!(serde_json::from_value::<CloseTerminalTabParams>(
            json!({"handle": "x", "discardUnsaved": true})
        )
        .is_err());
    }

