    #[test]
    fn test_count_repos_in_missing_dir_is_zero() {
        let dir = std::env::temp_dir().join(format!("codesense-missing-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        assert_eq!(count_repos_in(&dir), 0);
    }

    #[test]
    fn test_count_repos_in_counts_subdirs_only() {
        let dir = std::env::temp_dir().join(format!("codesense-count-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("repo-a")).unwrap();
        std::fs::create_dir_all(dir.join("repo-b")).unwrap();
        std::fs::create_dir_all(dir.join("repo-c")).unwrap();
        // A loose file in the contexts dir must NOT be counted as a repo.
        std::fs::write(dir.join("not-a-repo.txt"), b"x").unwrap();

        assert_eq!(count_repos_in(&dir), 3);

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn test_count_repos_in_unreadable_dir_is_zero() {
        // An unreadable dir makes read_dir return Err → count must be 0, not a panic.
        let dir = std::env::temp_dir().join(format!("codesense-unreadable-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&dir, std::fs::Permissions::from_mode(0o000)).unwrap();

            assert_eq!(count_repos_in(&dir), 0);

            // Restore permissions so cleanup can recurse in.
            std::fs::set_permissions(&dir, std::fs::Permissions::from_mode(0o755)).unwrap();
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

