/// MCP personal writes (routine_create / agent_create scope personal)
/// name their org explicitly; nothing falls back to the app's active org.
#[cfg(test)]
mod personal_placement_tests {
    use super::{personal_placement, placement_scope, PlacementRefusal};

    /// routine_create / agent_create go to the team unless Only me is asked for
    /// explicitly — the app's "Who can use it" default.
    #[test]
    fn a_create_with_no_scope_goes_to_the_team() {
        assert_eq!(placement_scope(None), "team");
        assert_eq!(placement_scope(Some("  ")), "team");
        assert_eq!(placement_scope(Some("team")), "team");
        assert_eq!(placement_scope(Some("personal")), "personal");
        assert_eq!(placement_scope(Some(" personal ")), "personal");
    }
    use crate::commands::scratch_identity::ScratchIdentity;

    fn me() -> ScratchIdentity {
        ScratchIdentity {
            profile_id: 7,
            handle: "me".into(),
            display_name: "Me".into(),
            avatar_url: None,
        }
    }

    fn synced() -> Vec<String> {
        vec!["acme/a".to_string(), "acme/b".to_string()]
    }

    #[test]
    fn a_personal_write_is_filed_in_the_named_org_only() {
        match personal_placement(me(), Some("acme/b".into()), None, &synced()) {
            Ok(crate::routines::Placement::Personal(owner)) => assert_eq!(owner.org, "acme/b"),
            _ => panic!("expected a personal placement in acme/b"),
        }
    }

    #[test]
    fn a_personal_write_without_an_org_is_refused_never_defaulted() {
        assert!(matches!(
            personal_placement(me(), None, None, &synced()),
            Err(PlacementRefusal::Scope(m)) if m.contains("needs `org`")
        ));
    }

    #[test]
    fn an_unsynced_org_or_a_team_is_refused() {
        assert!(matches!(
            personal_placement(me(), Some("ghost/org".into()), None, &synced()),
            Err(PlacementRefusal::Scope(m)) if m.contains("not synced")
        ));
        assert!(matches!(
            personal_placement(me(), Some("acme/a".into()), Some("core".into()), &synced()),
            Err(PlacementRefusal::Scope(_))
        ));
    }
}

/// Every path-addressed MCP writer refuses a path that lands in
/// all-orgs, or that a link carries into a scratch space, before it touches
/// anything. The `#[tool]` methods are bound to the desktop runtime, so each
/// tool's arguments are parsed as the agent sends them into the tool's own
/// params type and run through the gate the tool calls first; the wiring
/// test pins that each tool does call it first.
#[cfg(test)]
mod scratch_write_gate_tests {
    use super::*;
    use crate::context_repo::scratch_space::{scratch_all_orgs_root, scratch_org_root};

    const TOOLS: [&str; 4] = [
        "apply_canvas",
        "set_epic_repos",
        "delete_content_file",
        "move_content_file",
    ];

    /// `tool`'s arguments writing `target` (a move moves a team file there).
    fn args(tool: &str, target: &Path, team_file: &Path) -> serde_json::Value {
        match tool {
            "apply_canvas" => serde_json::json!({ "path": target, "elements": [] }),
            "set_epic_repos" => serde_json::json!({ "epicFilePath": target, "repos": [] }),
            "delete_content_file" => serde_json::json!({ "path": target }),
            "move_content_file" => serde_json::json!({ "fromPath": team_file, "toPath": target }),
            other => panic!("unknown tool {other}"),
        }
    }

    async fn gate(tool: &str, args: serde_json::Value) -> Result<(), ErrorData> {
        fn parsed<T: serde::de::DeserializeOwned>(args: serde_json::Value) -> T {
            serde_json::from_value(args).expect("the agent's arguments parse")
        }
        match tool {
            "apply_canvas" => refuse_scratch_writes(&parsed::<ApplyCanvasParams>(args)).await,
            "set_epic_repos" => refuse_scratch_writes(&parsed::<SetEpicReposParams>(args)).await,
            "delete_content_file" => {
                refuse_scratch_writes(&parsed::<DeleteContentFileParams>(args)).await
            }
            "move_content_file" => {
                refuse_scratch_writes(&parsed::<MoveContentFileParams>(args)).await
            }
            other => panic!("unknown tool {other}"),
        }
    }

    #[tokio::test]
    async fn each_path_writer_refuses_all_orgs_and_links_into_a_scratch_space() {
        let tmp = tempfile::tempdir().unwrap();
        let home = tmp.path();
        let me = Principal::from(7u64);
        let all_orgs = scratch_all_orgs_root(home, &me);
        let space_b = scratch_org_root(home, &me, "acme/b")
            .unwrap()
            .join("content");
        let team = home.join("users/7/orgs/acme/a/default/content");
        for dir in [&all_orgs.join("prompts"), &space_b, &team] {
            std::fs::create_dir_all(dir).unwrap();
        }
        std::os::unix::fs::symlink(&all_orgs, team.join("carried")).unwrap();
        std::os::unix::fs::symlink(&space_b, team.join("b")).unwrap();
        let team_file = team.join("doc.md");
        std::fs::write(&team_file, "doc").unwrap();

        for tool in TOOLS {
            for target in [
                all_orgs.join("prompts/p.md"),
                home.join("users/7/Scratch/ALL-ORGS/prompts/p.md"),
                team.join("carried/prompts/p.md"),
                team.join("b/x.md"),
            ] {
                let refused = gate(tool, args(tool, &target, &team_file))
                    .await
                    .expect_err(&format!("{tool} refuses {}", target.display()));
                assert!(
                    refused.message.contains("all-orgs") || refused.message.contains("link"),
                    "{tool}: {}",
                    refused.message
                );
            }
            gate(tool, args(tool, &team.join("new.md"), &team_file))
                .await
                .unwrap_or_else(|e| panic!("{tool} admits a team path: {}", e.message));
        }
        // A move OUT of all-orgs is a write there too.
        let refused = gate(
            "move_content_file",
            args(
                "move_content_file",
                &team.join("new.md"),
                &all_orgs.join("prompts/p.md"),
            ),
        )
        .await;
        assert!(refused.is_err());
    }

    /// Each path-addressed writer runs the gate as its first statement.
    #[test]
    fn each_path_writer_runs_the_gate_first() {
        let source = include_str!("handler.rs");
        for tool in TOOLS {
            let at = source
                .find(&format!("    async fn {tool}(\n"))
                .unwrap_or_else(|| panic!("{tool} is a tool"));
            let body = &source[at..];
            let open = body
                .find(") -> Result<CallToolResult, ErrorData> {\n")
                .unwrap();
            let first = body[open..].lines().nth(1).unwrap().trim();
            assert_eq!(first, "refuse_scratch_writes(&params).await?;", "{tool}");
        }
    }
}

#[cfg(test)]
mod self_sufficient_description_tests {
    use super::CodesenseHandler;

    /// The tools an agent sets CodeSense up with. Their descriptions are the whole contract:
    /// nothing may depend on a skill being installed or a pack existing.
    const SETUP_TOOLS: [&str; 9] = [
        "agent_create",
        "agent_update",
        "agent_get",
        "agent_list",
        "routine_create",
        "routine_update",
        "routine_get",
        "routine_list",
        "describe_setup",
    ];

    /// The prose of a description: `code spans` dropped, since a span is a literal value
    /// (a content path such as `.claude/skills/x/`, a field name), never an instruction to
    /// install or rely on anything.
    fn prose(description: &str) -> String {
        assert_eq!(
            description.matches('`').count() % 2,
            0,
            "unbalanced code spans: {description}"
        );
        description
            .split('`')
            .step_by(2)
            .collect::<Vec<_>>()
            .join(" ")
            .to_lowercase()
    }

    fn has_word(text: &str, word: &str) -> bool {
        text.split(|c: char| !c.is_alphanumeric())
            .any(|token| token == word)
    }

    #[test]
    fn setup_tool_descriptions_never_lean_on_installed_skills() {
        let router = CodesenseHandler::served_tool_router();
        for name in SETUP_TOOLS {
            let description = router
                .get(name)
                .and_then(|tool| tool.description.clone())
                .unwrap_or_else(|| panic!("{name} is served with a description"));
            let text = prose(&description);
            for word in ["skill", "skills", "pack", "packs"] {
                assert!(
                    !has_word(&text, word),
                    "{name} says {word:?}: {description}"
                );
            }
            for phrase in ["install the", "starter pack"] {
                assert!(
                    !text.contains(phrase),
                    "{name} says {phrase:?}: {description}"
                );
            }
        }
    }

    /// What the retired `/agent` and `/routine` skills taught now lives in what
    /// the tools are served with: their descriptions and their parameters' own.
    #[test]
    fn setup_tool_descriptions_carry_what_the_skills_taught() {
        let router = CodesenseHandler::served_tool_router();
        let description = |name: &str| {
            router
                .get(name)
                .map(super::tests::served_text)
                .unwrap_or_else(|| panic!("{name} is served"))
        };
        let agent_create = description("agent_create");
        for needle in [
            "builtin/claude",
            "permissions",
            "startup",
            "\"runtime\":\"codex\"",
            "A prompt or routine task starting with `/name`",
            "scope",
        ] {
            assert!(
                agent_create.contains(needle),
                "agent_create lacks {needle:?}"
            );
        }
        assert!(description("agent_list").contains("Copy to Mine"));
        assert!(description("agent_get").contains("To copy an agent"));
        let routine_create = description("routine_create");
        for needle in [
            "weekdays 08:30",
            "{{last_run_at}}",
            "\"when\":\"weekdays 09:00\"",
            "builtin/codex",
            "a `/name` task missing from the agent's `startup`",
            "`personal`",
            "signal_done",
        ] {
            assert!(
                routine_create.contains(needle),
                "routine_create lacks {needle:?}"
            );
        }
        assert!(description("describe_setup").contains("routine_create"));
    }
}

/// An agent's `kind` reaches `send_message` and `reply` as it sent it, and
/// only the two spellings are accepted.
#[cfg(test)]
mod message_kind_param_tests {
    use super::{ReplyParams, SendMessageParams};
    use crate::weft::inbox::MessageKind;
    use serde_json::json;

    #[test]
    fn send_message_and_reply_read_the_kind_an_agent_sends() {
        let send: SendMessageParams =
            serde_json::from_value(json!({"to": "human", "text": "ship it?", "kind": "needs-you"}))
                .unwrap();
        assert_eq!(send.kind, Some(MessageKind::NeedsYou));
        let plain: SendMessageParams =
            serde_json::from_value(json!({"to": "human", "text": "merged"})).unwrap();
        assert_eq!(plain.kind, None);
        let reply: ReplyParams =
            serde_json::from_value(json!({"messageId": 7, "text": "done", "kind": "update"}))
                .unwrap();
        assert_eq!(reply.kind, Some(MessageKind::Update));
        for bad in ["urgent", "Needs-You", " update"] {
            assert!(
                serde_json::from_value::<SendMessageParams>(
                    json!({"to": "human", "text": "x", "kind": bad})
                )
                .is_err(),
                "{bad} is refused"
            );
        }
    }

    #[test]
    fn the_schemas_offer_the_two_kinds() {
        for schema in [
            serde_json::to_string(&schemars::schema_for!(SendMessageParams)).unwrap(),
            serde_json::to_string(&schemars::schema_for!(ReplyParams)).unwrap(),
        ] {
            assert!(
                schema.contains("needs-you") && schema.contains("\"update\""),
                "{schema}"
            );
        }
    }
}

