/// Complete production boundary: capture admitted bytes before global webview dispatch.
async fn render_canvas_request<R: tauri::Runtime>(
    app: &tauri::AppHandle<R>,
    session: Option<&str>,
    remote: Option<commands::dashboard_launch::LaunchTeam>,
    params: RenderCanvasParams,
) -> Result<CallToolResult, ErrorData> {
    // Only canvases. Accept the context sandbox OR a registered
    // source-repo attachment / worktree — mirrors `apply_canvas`'s widened
    // write gate (MCP architectural reframe) so an agent that authored a
    // canvas into a source-repo clone can read it back by its real path.
    if !is_excalidraw_path(&params.path) {
        return Err(ErrorData::invalid_params(
            "path must be a .excalidraw file",
            None,
        ));
    }
    let scope = crate::context_repo::caller_scope::for_session(app, session, remote).await;
    let path = PathBuf::from(&params.path);
    let scene_scope = scope.clone();
    let scene_json = commands::await_blocking("render_canvas.read", move || {
        scene_scope.read_admitted(&path)
    })
    .await
    .map_err(|e| ErrorData::invalid_params(e, None))?;
    commands::files::validate_canvas_read_path(&params.path, app)
        .map_err(|e| ErrorData::invalid_params(e, None))?;

    // Register a oneshot, ask the webview to render, await the reply.
    let registry = app
        .try_state::<CanvasRenderRegistry>()
        .ok_or_else(|| ErrorData::internal_error("canvas render registry not registered", None))?;
    let (request_id, rx) = registry.register();

    app
            .emit(
                "canvas:render-request",
                serde_json::json!({ "requestId": request_id, "path": params.path, "sceneJson": scene_json }),
            )
            .map_err(|e| {
                // Nothing will reply — reclaim the registry slot before bailing.
                registry.take(&request_id);
                emit_err(e)
            })?;

    // Bound the wait so a missing webview (headless/cron, or app not
    // running) degrades to a clear error instead of hanging forever.
    // Peel the two transport layers with `?`: outer = the timeout (reclaim
    // the registry slot and surface an actionable "app not running"
    // error on elapse); middle = the oneshot channel. What remains is the
    // frontend's own render result.
    let render_result = tokio::time::timeout(
            std::time::Duration::from_secs(RENDER_CANVAS_TIMEOUT_SECS),
            rx,
        )
        .await
        .map_err(|_elapsed| {
            registry.take(&request_id);
            ErrorData::invalid_params(
                "canvas render timed out — open the CodeSense app so the render can run in its window (headless/cron runs can't render a canvas)",
                None,
            )
        })?
        .map_err(|_canceled| {
            ErrorData::internal_error("canvas render bridge closed before a result arrived", None)
        })?;

    match render_result {
        Ok(png_base64) => {
            // MCP architectural reframe: inline PNG bytes (no sidecar).
            // Validate the base64 so a corrupt payload surfaces as a tool
            // error, and compute `byteLen` from the decoded bytes so the
            // metadata is grounded in what we actually encode on the wire.
            let bytes = base64::engine::general_purpose::STANDARD
                .decode(png_base64.as_bytes())
                .map_err(|e| {
                    ErrorData::internal_error(
                        format!("canvas render returned invalid base64: {e}"),
                        None,
                    )
                })?;
            let byte_len = bytes.len();
            let meta_text = serde_json::to_string(&serde_json::json!({
                    "sourcePath": params.path,
                    "mimeType": "image/png",
                    "byteLen": byte_len,
                    "note": "Inline PNG — the image content block carries the base64 bytes directly. No sidecar is written.",
                }))
                .map_err(|e| {
                    ErrorData::internal_error(format!("response serialization failed: {}", e), None)
                })?;
            Ok(CallToolResult::success(vec![
                ContentBlock::image(png_base64, "image/png".to_string()),
                ContentBlock::text(meta_text),
            ]))
        }
        Err(msg) => Err(ErrorData::invalid_params(
            format!("canvas render failed: {msg}"),
            None,
        )),
    }
}

async fn validate_live_data_request(
    scope: crate::context_repo::caller_scope::CallerScope,
    params: ValidateLiveDataParams,
) -> Result<CallToolResult, ErrorData> {
    let file_path = params.path.clone().unwrap_or_default();
    let text = match (params.content, params.path) {
        (Some(text), _) => text,
        (None, Some(path)) => {
            crate::commands::await_blocking("read dashboard for validation", move || {
                scope.read_admitted(std::path::Path::new(&path))
            })
            .await
            .map_err(|e| ErrorData::invalid_params(e, None))?
        }
        _ => return Err(ErrorData::invalid_params("provide path or content", None)),
    };
    ok_json(super::live_data_authoring::lint_live_data_doc(
        &text,
        &file_path,
        &[],
    ))
}

async fn validate_story_request<R: tauri::Runtime>(
    app: &tauri::AppHandle<R>,
    session: Option<&str>,
    remote: Option<commands::dashboard_launch::LaunchTeam>,
    params: ValidateStoryParams,
) -> Result<CallToolResult, ErrorData> {
    let scope = crate::context_repo::caller_scope::for_session(app, session, remote).await;
    // Resolve the candidate's (text, optional path anchor).
    let (text, path_buf) = match (params.path, params.content) {
        (Some(p), Some(c)) => (c, Some(PathBuf::from(p))),
        (Some(p), None) => {
            let pb = PathBuf::from(&p);
            let t = scope
                .read_admitted(&pb)
                .map_err(|e| ErrorData::invalid_params(e, None))?;
            (t, Some(pb))
        }
        (None, Some(c)) => (c, None),
        (None, None) => {
            return Err(ErrorData::invalid_params(
                "provide `path` and/or inline `content`",
                None,
            ));
        }
    };
    let report = commands::story_create::validate_story_in_context_for(
        app,
        &text,
        path_buf.as_deref(),
        &scope,
    )
    .await
    .map_err(|e| ErrorData::invalid_params(e, None))?;
    ok_json(report)
}

