#[cfg(test)]
mod agent_account_tool_tests {
    use super::*;
    use crate::install::agent_account_store::{
        AccountResolutionAvailability, AccountResolutionFreshness, AccountResolutionReason,
        AccountResolutionSource, AgentAccountAuthState, AgentAccountProfile, AgentProvider,
    };

    fn profile(id: &str, detached: bool) -> AgentAccountProfile {
        AgentAccountProfile {
            schema_version: 1,
            id: id.into(),
            provider: AgentProvider::Claude,
            label: id.into(),
            auth_state: AgentAccountAuthState::Ready,
            auth_checked_at: None,
            auth_error: None,
            identity: None,
            status_line: None,
            generation: 1,
            created_at: 1,
            updated_at: 1,
            detached_at: detached.then_some(2),
            pending_lifecycle_events: Vec::new(),
        }
    }

    fn resolution(eligible: bool) -> commands::agent_accounts::AgentAccountResolutionView {
        commands::agent_accounts::AgentAccountResolutionView {
            runtime: codesense_pty_core::agent_cli::AgentCli::Claude,
            source: AccountResolutionSource::Explicit,
            account_id: None,
            provider: Some(AgentProvider::Claude),
            label: None,
            generation: None,
            reason: AccountResolutionReason::AccountMissing,
            availability: AccountResolutionAvailability::Unavailable,
            freshness: AccountResolutionFreshness::Unknown,
            spawn_eligible: eligible,
        }
    }

    #[test]
    fn the_list_hides_detached_accounts_unless_asked() {
        let profiles = vec![profile("a", false), profile("b", true)];
        let attached = listed_agent_accounts(profiles.clone(), false);
        assert_eq!(attached.len(), 1);
        assert_eq!(attached[0].id, "a");
        let all = listed_agent_accounts(profiles, true);
        assert_eq!(all.len(), 2);
        assert!(all.iter().any(|a| a.id == "b" && a.detached_at.is_some()));
    }

    #[test]
    fn a_refusal_echoes_the_requested_account_and_never_a_home() {
        let refused = resolution_with_request(resolution(false), Some("gone".into())).unwrap();
        assert_eq!(refused["requestedAccountId"], "gone");
        assert_eq!(refused["reason"], "account-missing");
        let text = refused.to_string();
        assert!(!text.contains("home") && !text.contains("credential"));
        let allowed = resolution_with_request(resolution(true), Some("a".into())).unwrap();
        assert!(allowed.get("requestedAccountId").is_none());
        let unrequested = resolution_with_request(resolution(false), None).unwrap();
        assert!(unrequested.get("requestedAccountId").is_none());
    }

    #[test]
    fn the_account_tool_descriptions_state_their_rules() {
        let router = CodesenseHandler::served_tool_router();
        let describe = |name: &str| router.get(name).unwrap().description.clone().unwrap();
        assert!(describe("resolve_agent_account").contains("ignores per-agent pins"));
        assert!(describe("resolve_agent_account").contains("account-missing"));
        assert!(describe("set_active_agent_account").contains("For people only"));
        assert!(describe("list_agent_accounts").contains("includeDetached"));
    }
}
